(window.EX_CHUNKS=window.EX_CHUNKS||{})["b62"]={"日用品":[["超市里摆满了各种日用品。","سۇپېرماركېت ھەر خىل كۈندىلىك تۇرمۇش بۇيۇملىرى بىلەن تولۇپ كەتكەن.","supérmarkét her xil kündilik turmush buyumliri bilen tolup ketken."]],"后背":[["阳光照在他的后背上，暖洋洋的。","قۇياش نۇرى ئۇنىڭ دۈمبىسىگە چۈشۈپ، ئىللىق ھېس قىلدۇردى.","quyash nuri uning dümbisige chüshüp, illiq hés qildurdi."]],"肥沃":[["这片土地十分肥沃。","بۇ يەر ئىنتايىن مۇنبەت.","bu yer intayin munbet."]],"各抒己见":[["会议上大家各抒己见，讨论热烈。","يىغىندا ھەممەيلەن ئۆز كۆز قارىشىنى ئوتتۇرىغا قويدى، مۇھاكىمە قىزغىن بولدى.","yighinda hemmeylen öz köz qarishini otturigha qoydi, muhakime qizghin boldi."]],"伤脑筋":[["这道数学题真伤脑筋。","بۇ ماتېماتىكا مەسىلىسى ھەقىقەتەن بېشىمنى قاتۇردى.","bu matématika mesilisi heqiqeten béshimni qaturdi."]],"权衡":[["在做决定前，需要仔细权衡利弊。","قارار چىقىرىشتىن بۇرۇن، پايدا-زىياننى ئېنىق ئۆلچەش كېرەك.","qarar chiqirishtin burun, payda-ziyanni éniq ölchesh kérek."]],"厾":[["她温柔地轻厾他的脸颊。","ئۇ ئۇنىڭ يۈزىگە ئاستا تەگدى.","u uning yüzige asta tegdi."]],"圾":[["垃圾应该分类投放。","ئەخلەتلەرنى تۈرگە ئايرىپ تاشلاش كېرەك.","exletlerni türge ayrip tashlash kérek."]],"斾":[["这种旗帜叫作斾旗。","بۇ خىل بايراق پەي بايرىقى دەپ ئاتىلىدۇ.","bu xil bayraq pey bayriqi dep atilidu."]],"歾":[["他歾尽了所有积蓄。","ئۇ بارلىق ئامانەت پۇلىنى خەجلەپ تۈگەتتى.","u barliq amanet pulini xejlep tügetti."]],"箾":[["箾竹适合用来编织工艺品。","ئىنچىكە بامبۇك ھۈنەر-سەنئەت بۇيۇملىرىنى توقۇشقا ماس كېلىدۇ.","inchike bambuk hüner-sen'et buyumlirini toqushqa mas kélidu."]],"薾":[["薾是一种草类植物。","ئەر بىر خىل ئوت ئۆسۈملۈكى.","er bir xil ot ösümlüki."]],"褾":[["褾衣的领口设计独特，很有个性。","كۆڭلەكنىڭ ياقىسىنىڭ لايىھەسى ئالاھىدە، ئىنتايىن شەخسىيەتلىك.","könglekning yaqisining layihesi alahide, intayin shexsiyetlik."]],"轾":[["车轾是车轮与地面接触的部分。","ھارۋا چاقى چاق بىلەن يەر يۈزى تەگكەن قىسمىدۇر.","harwa chaqi chaq bilen yer yüzi tegken qismidur."]],"陾":[["陾密森林中隐藏着宝藏。","زىچ ئورمان ئىچىدە خەزىنە يوشۇرۇنغان.","zich orman ichide xezine yoshurunghan."]],"饾":[["这些糖果摆得真饾饾。","بۇ كەمپۈتلەر ناھايىتى تىزىلىپتۇ.","bu kempütler nahayiti tiziliptu."]],"魾":[["魾鱼的颜色会随着环境变化。","پەنجىر بېلىقىنىڭ رەڭگى مۇھىت ئۆزگىرىشىگە ئەگىشىپ ئۆزگىرىدۇ.","penjir béliqining renggi muhit özgirishige egiship özgiridu."]],"駾":[["駾马在草原上自由驰骋。","قاچقان ئات يايلاقتا ئەركىن چاپىدۇ.","qachqan at yaylaqta erkin chapidu."]],"一时间":[["一时间大家都沉默了。","بىر ئاز ۋاقىت ئىچىدە ھەممەيلەن جىم قالدى.","bir az waqit ichide hemmeylen jim qaldi."]],"丁卯胡乱":[["丁卯胡乱是一场规模较大的社会动荡事件。","دىڭماۋ قالايمىقانچىلىقى كۆلىمى بىر قەدەر چوڭ بولغان ئىجتىمائىي تۇراقسىزلىق ۋەقەسى.","dingmaw qalaymiqanchiliqi kölimi bir qeder chong bolghan ijtimaiy turaqsizliq weqesi."]],"七星区":[["七星区是这座城市的一个区域。","يەتتە يۇلتۇز رايونى بۇ شەھەرنىڭ بىر رايونى.","yette yultuz rayoni bu sheherning bir rayoni."]],"三月份":[["三月份是公历的第三个月。","ئۈچىنچى ئاي مىلادىيە كالېندارىنىڭ ئۈچىنچى ئېيى.","üchinchi ay miladiye kaléndarining üchinchi éyi."]],"三番两次":[["这个问题已经三番两次地出现。","بۇ مەسىلە ئاللىبۇرۇن ئۈچ-ئىككى قېتىم كۆرۈلدى.","bu mesile alliburun üch-ikki qétim körüldi."]],"上合":[["上合会议即将召开。","شاڭخەي ھەمكارلىق تەشكىلاتى يىغىنى ئېچىلماقچى.","shangxey hemkarliq teshkilati yighini échilmaqchi."]],"上坡段":[["这段路是典型的上坡段。","بۇ يول تىپىك يۇقىرىغا چىقىش بۆلىكى.","bu yol tipik yuqirigha chiqish böliki."]],"下订单":[["请在线上下订单。","توردا زاكاز بېرىڭ.","torda zakaz béring."]],"上议院":[["上议院通过法案。","تەرجىمە قىلىنغان جۈملىلەر:","terjime qilinghan jümliler:"]],"上辈":[["上辈人留下的传统至今仍在延续。","تەرجىمە قىلىنغان جۈملىلەر:","terjime qilinghan jümliler:"]],"不拘小节":[["他向来不拘小节。","ئۇ ئەزەلدىن كىچىك ئىشلارغا پەرۋا قىلمايدۇ.","u ezeldin kichik ishlargha perwa qilmaydu."]],"丙烷":[["丙烷是常用的燃料气体。","پروپان ئادەتتە ئىشلىتىلىدىغان يېقىلغۇ گازىدۇر.","propan adette ishlitilidighan yéqilghu gazidur."]],"世风日下":[["世风日下，令人担忧。","دۇنيانىڭ ئەھۋالى كۈندىن-كۈنگە ناچارلىشىپ، كىشىلەرنى ئەندىشىگە سالىدۇ.","dunyaning ehwali kündin-künge nacharliship, kishilerni endishige salidu."]],"中国证券报":[["《中国证券报》分析了股市动态。","«جۇڭگو پاي چېكى گېزىتى» پاي چېكى بازارىنىڭ ئەھۋالىنى تەھلىل قىلدى.","«junggo pay chéki géziti» pay chéki bazarining ehwalini tehlil qildi."]],"中法新约":[["中法新约促进了双边关系。","جۇڭگو-فرانسىيە يېڭى شەرتنامىسى ئىككى تەرەپ مۇناسىۋىتىنى ئىلگىرى سۈردى.","junggo-fransiye yéngi shertnamisi ikki terep munasiwitini ilgiri sürdi."]],"摔倒":[["他不小心在湿滑的地面上摔倒了。","ئۇ سىيرىلماق يەردە سەۋەنسىز يىقىلىپ چۈشتى.","u siyrilmaq yerde sewensiz yiqilip chüshti."]],"九尾龟":[["九尾龟是一种古老的传说动物。","جۇۋېي تاشپاقىسى قەدىمىي بىر رىۋايەت ھايۋانى.","juwéy tashpaqisi qedimiy bir riwayet haywani."]],"乙烷":[["乙烷是天然气中主要成分之一。","ئېتان تەبىئىي گازنىڭ ئاساسلىق تەركىبىي قىسىملىرىنىڭ بىرى.","étan tebiiy gazning asasliq terkibiy qisimlirining biri."]],"乳制品":[["乳制品包括奶酪和酸奶。","سۈت مەھسۇلاتلىرىغا پىشلاق ۋە قېتىق كىرىدۇ.","süt mehsulatlirigha pishlaq we qétiq kiridu."]],"干冰":[["干冰用于食品保鲜。","قۇرۇق مۇز يېمەكلىكلەرنى تازا ساقلىشقا ئىشلىتىلىدۇ.","quruq muz yémekliklerni taza saqlishqa ishlitilidu."]],"井绳":[["井绳用结实的麻绳制成。","قۇدۇق ئارغامچىسى پۇختا كەندىر ئارغامچىدىن ياسىلىدۇ.","quduq arghamchisi puxta kendir arghamchidin yasilidu."]],"交欢":[["交欢是亲密关系的体现。","جىنسىي مۇناسىۋەت يېقىن مۇناسىۋەتنىڭ ئىپادىسى.","jinsiy munasiwet yéqin munasiwetning ipadisi."]],"享誉":[["这家餐厅享誉全国。","بۇ رېستوران پۈتۈن مەملىكەتكە داڭلىق.","bu réstoran pütün memliketke dangliq."]],"交头接耳":[["他们在角落里交头接耳，讨论秘密计划。","ئۇلار بۇلۇڭدا قۇلاق-قۇلاققا چۈشۈپ مەخپىي پىلاننى مۇزاكىرە قىلدى.","ular bulungda qulaq-qulaqqa chüshüp mexpiy pilanni muzakire qildi."]],"人财两空":[["投资失败让他人财两空，十分可惜。","مەبلەغ سېلىش مەغلۇبىيىتى ئۇنى ھەم پۇلىدىن ھەم ئادىمىدىن ئايرىۋەتتى، بەك ئەپسۇس.","meblegh sélish meghlubiyiti uni hem pulidin hem adimidin ayriwetti, bek epsus."]],"京沪":[["京沪高铁是中国第一条时速超过300公里的高铁线路。","جىڭ-خۇ يۇقىرى سۈرئەتلىك تۆمۈريولى جۇڭگونىڭ سائەتلىك سۈرئىتى 300 كىلومېتىردىن ئاشىدىغان تۇنجى يۇقىرى سۈرئەتلىك تۆمۈريول لىنىيەسى.","jing-xu yuqiri sür'etlik tömüryoli junggoning saetlik sür'iti 300 kilométirdin ashidighan tunji yuqiri sür'etlik tömüryol liniyesi."]],"亮氨酸":[["亮氨酸是人体必需氨基酸。","لېيۇسىن ئىنسان بەدىنىگە زۆرۈر ئامىنو كىسلاتاسى.","léyusin insan bedinige zörür amino kislatasi."]],"京郊日报":[["《京郊日报》主要报道北京周边地区的新闻。","«جىڭجياۋ كۈندىلىك گېزىتى» ئاساسلىقى بېيجىڭ ئەتراپىدىكى رايونلارنىڭ خەۋەرلىرىنى خەۋەر قىلىدۇ.","«jingjyaw kündilik géziti» asasliqi béyjing etrapidiki rayonlarning xewerlirini xewer qilidu."]],"仁弟":[["这位仁弟是我的好伙伴。","بۇ مېھرىبان ئىنىم مېنىڭ ياخشى ھەمراھىم.","bu méhriban inim méning yaxshi hemrahim."]],"代码":[["这段代码运行正常。","بۇ كود نورمال ئىجرا بولماقتا.","bu kod normal ijra bolmaqta."]],"代数结构":[["代数结构定义运算和元素关系。","جەبرىي قۇرۇلما مەشغۇلاتلار بىلەن ئېلېمېنتلار مۇناسىۋىتىنى ئېنىقلايدۇ.","jebriy qurulma meshghulatlar bilen éléméntlar munasiwitini éniqlaydu."]],"仕女":[["画中的仕女姿态优雅，神情娴静。","رەسىمدىكى ساراي ئاياللىرىنىڭ ھالىتى نەپىس، روھىي ھالىتى جىمجىت.","resimdiki saray ayallirining haliti nepis, rohiy haliti jimjit."]],"代币":[["这个代币可用于支付服务费用。","بۇ توكېن مۇلازىمەت ھەققىنى تۆلەشكە ئىشلىتىلىدۇ.","bu tokén mulazimet heqqini töleshke ishlitilidu."]],"企业管理":[["良好的企业管理至关重要。","ياخشى كارخانا باشقۇرۇش ئىنتايىن مۇھىم.","yaxshi karxana bashqurush intayin muhim."]],"伊利亚特":[["《伊利亚特》是古代史诗。","«ئىلىئادا» قەدىمكى داستان.","«iliada» qedimki dastan."]],"布莱特妮·墨菲":[["布莱特妮·墨菲是一位演员。","بىرىتتىنى مۇرفى بىر ئارتىس.","birittini murfi bir artis."]],"佝偻":[["老人佝偻着背，步履蹒跚。","بوۋاي بېلىنى بۈكۈپ، ئېغىر-بېسىق ئىلگىرىلەيدۇ.","boway bélini büküp, éghir-bésiq ilgirileydu."]],"你看着办吧":[["你看着办吧，别出错。","ئۆزۈڭ قاراپ قىل، خاتالىق چىقىرمىغىن.","özüng qarap qil, xataliq chiqirmighin."]],"佩奇":[["佩奇是《小猪佩奇》的主角。","پېپپا «كىچىك چوشقا پېپپا» نىڭ باش پېرسوناژى.","péppa «kichik choshqa péppa» ning bash pérsonazhi."]],"侍卫":[["侍卫忠诚地守护着宫殿安全。","قاراۋۇل ئەسكەرلەر ساراينىڭ بىخەتەرلىكىنى سادىقلىق بىلەن قوغدايدۇ.","qarawul eskerler sarayning bixeterlikini sadiqliq bilen qoghdaydu."]],"俄罗斯人":[["俄罗斯人大多居住在东部。","ئورۇسلارنىڭ كۆپىنچىسى شەرقىي رايوندا ياشايدۇ.","oruslarning köpinchisi sherqiy rayonda yashaydu."]],"便捷化":[["这项服务让流程更加便捷化。","بۇ مۇلازىمەت جەرياننى تېخىمۇ قولايلىقلاشتۇردى.","bu mulazimet jeryanni téximu qolayliqlashturdi."]],"俏皮话":[["他经常用俏皮话来逗大家开心。","ئۇ ھەمىشە چاقچاق سۆزلەر بىلەن كۆپچىلىكنى كۈلدۈرىدۇ.","u hemishe chaqchaq sözler bilen köpchilikni küldüridu."]],"保护者":[["志愿者们是野生动物的重要保护者。","پىدائىيلار ياۋايى ھايۋانلارنىڭ مۇھىم قوغدىغۇچىلىرى.","pidaiylar yawayi haywanlarning muhim qoghdighuchiliri."]],"信用证券":[["信用证券在市场中表现良好。","ئىشەنچ ئىناۋىتى قىممەتلىك قەغىزى بازاردا ياخشى نەتىجە كۆرسەتتى.","ishench inawiti qimmetlik qeghizi bazarda yaxshi netije körsetti."]],"信使":[["信使准时将信件送到了目的地。","خەت يەتكۈزگۈچى خەتنى ۋاقتىدا مەنزىلگە يەتكۈزدى.","xet yetküzgüchi xetni waqtida menzilge yetküzdi."]],"倘或":[["倘或下雨，我们就不出门了。","ئەگەر يامغۇر ياغسا، بىز ئۆيدىن چىقمايمىز.","eger yamghur yaghsa, biz öydin chiqmaymiz."]],"倚托":[["事情可以倚托他办。","ئىشنى ئۇنىڭغا تاپشۇرۇپ قىلغىلى بولىدۇ.","ishni uninggha tapshurup qilghili bolidu."]],"仓山":[["仓山风景优美。","ئامبار تېغىنىڭ مەنزىرىسى گۈزەل.","ambar téghining menzirisi güzel."]],"个人主义":[["他坚持个人主义，不愿合作。","ئۇ شەخسىيەتچىلىكنى تۇتۇپ، ھەمكارلىشىشقا ئۇنىمىدى.","u shexsiyetchilikni tutup, hemkarlishishqa unimidi."]],"值机":[["请前往柜台值机。","ساقلىغۇچ ئورنىغا بېرىپ تىزىملىتىڭ.","saqlighuch ornigha bérip tizimliting."]],"伪阳性":[["测试结果显示了伪阳性。","سىناق نەتىجىسىدە يالغان مۇسبەتلىك كۆرۈلدى.","sinaq netijiside yalghan musbetlik körüldi."]],"备查":[["文件需备查以备不时之需。","ھۆججەتلەرنى كېرەك بولغاندا تەكشۈرۈش ئۈچۈن ساقلىشى كېرەك.","höjjetlerni kérek bolghanda tekshürüsh üchün saqlishi kérek."]],"催泪":[["这部电影催泪感人。","بۇ كىنو كۆز ياشلىق ۋە تەسىرلىك.","bu kino köz yashliq we tesirlik."]],"催泪大片":[["这部催泪大片让人动容。","بۇ كۆز ياشلىتىش فىلىمى كىشىنى ھەيران قالدۇرىدۇ.","bu köz yashlitish filimi kishini heyran qalduridu."]],"催眠曲":[["这首催眠曲让婴儿安然入睡。","بۇ ھىپنوز مۇزىكىسى بوۋاقنى تىنچ ئۇخلىتىدۇ.","bu hipnoz muzikisi bowaqni tinch uxlitidu."]],"债务证券":[["债务证券用于融资和借贷。","قەرز قىممەتلىك قەغىزى مەبلەغ توپلاش ۋە قەرز بېرىش-ئېلىشقا ئىشلىتىلىدۇ.","qerz qimmetlik qeghizi meblegh toplash we qerz bérish-élishqa ishlitilidu."]],"传神":[["他的表演传神生动。","ئۇنىڭ ئىپادىسى جانلىق ۋە تەسىرلىك ئىدى.","uning ipadisi janliq we tesirlik idi."]],"光照":[["充足的光照有助于植物生长。","يېتەرلىك نۇر چۈشۈش ئۆسۈملۈكلەرنىڭ ئۆسۈشىگە ياردەم قىلىدۇ.","yéterlik nur chüshüsh ösümlüklerning ösüshige yardem qilidu."]],"兄嫂":[["兄嫂对弟弟妹妹负有责任。","ئاكا-يەڭگىلەر ئىنى-سىڭىللارغا مەسئۇلىيەتچان بولۇشى كېرەك.","aka-yenggiler ini-singillargha mes'uliyetchan bolushi kérek."]],"免疫应答":[["免疫应答需要时间。","ئىممۇنىتېت جاۋابى ۋاقىت تەلەپ قىلىدۇ.","immunitét jawabi waqit telep qilidu."]],"光通量":[["光通量是衡量光照强度的指标。","نۇر ئېقىمى يورۇقلۇق كۈچىنى ئۆلچەيدىغان كۆرسەتكۈچ.","nur éqimi yoruqluq küchini ölcheydighan körsetküch."]],"入球":[["前锋成功入球，赢得胜利。","ھۇجۇمچى توپنى كىرگۈزۈشكە مۇۋەپپەقىيەت قازىنىپ، غەلىبىنى قولغا كەلتۈردى.","hujumchi topni kirgüzüshke muweppeqiyet qazinip, ghelibini qolgha keltürdi."]],"全麦":[["全麦面包更健康。","پۈتۈن بۇغداي نان تېخىمۇ ساغلام.","pütün bughday nan téximu saghlam."]],"内贾德":[["内贾德是前伊朗总统。","ئەھمەدى نەجاد ئىراننىڭ سابىق پرېزىدېنتى.","ehmedi nejad iranning sabiq prézidénti."]],"八仙桌":[["八仙桌是一种八人围坐的方桌。","بەشىيەن ئۈستىلى سەككىز كىشى چۆرىدەپ ئولتۇرىدىغان تۆت تەرەپلىك ئۈستەل.","beshiyen üstili sekkiz kishi chöridep olturidighan töt tereplik üstel."]],"八美乡":[["八美乡以美丽的自然风光闻名。","سەككىز گۈزەل يېزا گۈزەل تەبىئىي مەنزىرىسى بىلەن داڭلىق.","sekkiz güzel yéza güzel tebiiy menzirisi bilen dangliq."]],"两院":[["两院合作推动了多项重要法案。","ئىككى پالاتا ھەمكارلىشىپ نۇرغۇن مۇھىم قانۇن تەكلىپلىرىنى ئىلگىرى سۈردى.","ikki palata hemkarliship nurghun muhim qanun tekliplirini ilgiri sürdi."]],"两面":[["这件事有两面性，需要全面看待。","بۇ ئىشنىڭ ئىككى تەرىپى بار، ھەممە تەرەپتىن قاراش كېرەك.","bu ishning ikki teripi bar, hemme tereptin qarash kérek."]],"公职人员":[["这位公职人员为民服务很尽责。","بۇ ئاممىۋى خىزمەتچى خەلققە مۇلازىمەت قىلىشتا ئىنتايىن مەسئۇلىيەتچان.","bu ammiwi xizmetchi xelqqe mulazimet qilishta intayin mes'uliyetchan."]],"公猪":[["公猪在农场中负责配种。","ئاممىۋى چوشقا فېرمىدا ئۇرۇقداشقا مەسئۇلدۇر.","ammiwi choshqa férmida uruqdashqa mes'uldur."]],"公民权":[["公民权包括言论自由和集会自由。","پۇقرالىق ھوقۇقى سۆز ئەركىنلىكى ۋە يىغىلىش ئەركىنلىكىنى ئۆز ئىچىگە ئالىدۇ.","puqraliq hoquqi söz erkinliki we yighilish erkinlikini öz ichige alidu."]],"兵库":[["兵库储存着大量战略物资。","قورال-ياراغ ئامبىرىدا كۆپ مىقداردا ئىستراتېگىيەلىك ماتېرىياللار ساقلىنىدۇ.","qoral-yaragh ambirida köp miqdarda istratégiyelik matériyallar saqlinidu."]],"凌源市":[["凌源市历史悠久。","لىڭيۈەن شەھىرىنىڭ تارىخى ئۇزۇن.","lingyüen shehirining tarixi uzun."]],"分光计":[["实验室使用分光计检测光的波长。","تەجرىبىخانا نۇر ئايرىش ئۆلچەرگۈچى ئارقىلىق نۇرنىڭ دولقۇن ئۇزۇنلۇقىنى تەكشۈرىدۇ.","tejribixana nur ayrish ölchergüchi arqiliq nurning dolqun uzunluqini tekshüridu."]],"刑讯":[["刑讯逼供是违法的。","جازا سوراپ ئىقرار ئېلىش قانۇنغا خىلاپتۇر.","jaza sorap iqrar élish qanungha xilaptur."]],"划子":[["那艘小划子停在岸边。","ئۇ كىچىك قېيىق دەريا بويىدا توختاپ تۇرۇپتۇ.","u kichik qéyiq derya boyida toxtap turuptu."]],"列兵":[["列兵是军队中的最低军衔。","ئەسكەر ئارمىيەدىكى ئەڭ تۆۋەن ھەربىي ئەمەل.","esker armiyediki eng töwen herbiy emel."]],"前移式叉车":[["这种前移式叉车操作灵活。","بۇ ئالدىغا يۆتكىلىدىغان قارا ئاپپاراتنىڭ مەشغۇلاتى جانلىق.","bu aldigha yötkilidighan qara apparatning meshghulati janliq."]],"前夫":[["前夫已再婚。","ئالدىنقى يولدىشى قايتا توي قىلىپتۇ.","aldinqi yoldishi qayta toy qiliptu."]],"加州":[["加州的气候四季分明。","كالىفورنىيەنىڭ ھاۋاسى تۆت پەسىلدە ئېنىق پەرقلىنىدۇ.","kaliforniyening hawasi töt pesilde éniq perqlinidu."]],"勇略":[["他的勇略令人钦佩。","ئۇنىڭ باتۇرلۇق ۋە ئەقىل-پاراسىتى كىشىنى ھەيران قالدۇرىدۇ.","uning baturluq we eqil-parasiti kishini heyran qalduridu."]],"勒维纳斯":[["勒维纳斯是著名的哲学家。","لېۋىناس مەشھۇر پەلسەپىشۇناسدۇر.","léwinas meshhur pelsepishunasdur."]],"勋绩":[["他的勋绩被载入史册。","ئۇنىڭ تۆھپىسى تارىخنامىگە خاتىرىلەندى.","uning töhpisi tarixnamige xatirilendi."]],"包心菜":[["包心菜是一种蔬菜。","قاپلانغان كۆكتات بىر خىل كۆكتات.","qaplanghan köktat bir xil köktat."]],"包衣":[["包衣是古代的一种服饰。","قاپلانغان كىيىم قەدىمكى زاماندىكى بىر خىل كىيىم-كېچەك.","qaplanghan kiyim qedimki zamandiki bir xil kiyim-kéchek."]],"北极圈":[["北极圈气候寒冷。","شىمالىي قۇتۇپ چەمبىرىنىڭ ھاۋاسى سوغۇق.","shimaliy qutup chembirining hawasi soghuq."]],"汇入":[["资金已经成功汇入账户。","مەبلەغ ھېساباتقا مۇۋەپپەقىيەتلىك يۆتكەلدى.","meblegh hésabatqa muweppeqiyetlik yötkeldi."]],"北关区":[["北关区是城市的一个老城区。","شىمالىي بوغۇز رايونى شەھەرنىڭ كونا رايونى.","shimaliy boghuz rayoni sheherning kona rayoni."]],"千卡":[["千卡是热量单位，常用于食品标签。","كىلوكالورىيە ئىسسىقلىق بىرلىكى بولۇپ، كۆپىنچە يېمەكلىك ئېتىكېتلىرىدە ئىشلىتىلىدۇ.","kilokaloriye issiqliq birliki bolup, köpinche yémeklik étikétliride ishlitilidu."]],"南岳区":[["南岳区因衡山而闻名全国。","جەنۇبىي تاغ رايونى خېڭشەن تېغى بىلەن پۈتۈن مەملىكەتكە مەشھۇر.","jenubiy tagh rayoni xéngshen téghi bilen pütün memliketke meshhur."]],"南陵":[["南陵的山水风光令人陶醉。","نەنلىڭنىڭ تاغ-سۇ مەنزىرىسى كىشىنى مەست قىلىدۇ.","nenlingning tagh-su menzirisi kishini mest qilidu."]],"千载难逢":[["这样的机会千载难逢，不容错过。","بۇنداق پۇرسەت مىڭ يىلدا بىر كېلىدۇ، قولدىن بەرمەسلىك كېرەك.","bundaq purset ming yilda bir kélidu, qoldin bermeslik kérek."]],"北宋四大部书":[["北宋四大部书是中国古代的重要典籍。","شىمالىي سۇڭنىڭ تۆت چوڭ تۈزۈم كىتابى جۇڭگو قەدىمكى زامانىدىكى مۇھىم كلاسسىك ئەسەرلەردۇر.","shimaliy sungning töt chong tüzüm kitabi junggo qedimki zamanidiki muhim klassik eserlerdur."]],"去留":[["去留全凭个人选择。","كېتىش-قېلىش پۈتۈنلەي شەخسىي تاللاشقا باغلىق.","kétish-qélish pütünley shexsiy tallashqa baghliq."]],"叉烧":[["叉烧是广东名菜。","ئاچا كاۋاپ گۇاڭدۇڭنىڭ مەشھۇر تائامى.","acha kawap guangdungning meshhur taami."]],"叉簧":[["叉簧发出清脆的响声。","ئاچا پەلى ئېنىق ئاڭلىنىدۇ.","acha peli éniq anglinidu."]],"原核细胞型微生物":[["原核细胞型微生物致病性强。","پروكارىيوت ھۈجەيرىلىك مىكروئورگانىزملىرىنىڭ كېسەل قوزغىتىش كۈچى كۈچلۈك.","prokariyot hüjeyrilik mikroorganizmlirining késel qozghitish küchi küchlük."]],"原鸽":[["原鸽是一种常见的鸟类。","ئەسلىي كەپتەر ئادەتتىكى بىر خىل قۇش.","esliy kepter adettiki bir xil qush."]],"卡拉什尼科夫":[["卡拉什尼科夫是苏联著名枪械设计师。","كالاشنىكوۋ سوۋېت ئىتتىپاقىنىڭ داڭلىق قورال لايىھەلىگۈچىسى.","kalashnikow sowét ittipaqining dangliq qoral layiheligüchisi."]],"印刷电路板":[["印刷电路板是电子元件的基础。","بېسىلغان ئېلېكترونلۇق تاختىچە ئېلېكترون ئېلېمېنتلىرىنىڭ ئاساسى.","bésilghan éléktronluq taxtiche éléktron éléméntlirining asasi."]],"口说无凭":[["口说无凭，要有证据才行。","ئېغىز سۆزىنىڭ ئىسپاتى يوق، ئىسپات بولغاندىلا بولىدۇ.","éghiz sözining ispati yoq, ispat bolghandila bolidu."]],"口足目":[["口足目是古代的一种刑罚。","ئېغىز-پۇت جازاسى قەدىمكى زاماندىكى بىر خىل جازا ئىدى.","éghiz-put jazasi qedimki zamandiki bir xil jaza idi."]],"只可意会，不可言传":[["这句话只可意会，不可言传。","بۇ گەپنى پەقەت چۈشىنىشكە بولىدۇ، ئېيتىپ بېرەلمەيسەن.","bu gepni peqet chüshinishke bolidu, éytip bérelmeysen."]],"古波":[["古波是一位优秀的音乐家。","گۇبو ئېسىل مۇزىكانت.","gubo ésil muzikant."]],"反圣婴":[["反圣婴的概念在宗教中较少见。","ئەكس ئەلئارا چۈشەنچىسى دىندا ئاز ئۇچرايدۇ.","eks el'ara chüshenchisi dinda az uchraydu."]],"史记":[["这部《史记》记录了古代许多重要事件。","بۇ «تارىخ خاتىرىسى» قەدىمدىكى نۇرغۇن مۇھىم ۋەقەلەرنى خاتىرىلىگەن.","bu «tarix xatirisi» qedimdiki nurghun muhim weqelerni xatiriligen."]],"叻沙":[["这道叻沙的味道非常浓郁。","بۇ لاكسانىڭ تەمى ئىنتايىن قويۇق.","bu laksaning temi intayin qoyuq."]],"合集":[["这本合集包含多个故事。","بۇ توپلام كۆپلىگەن ھېكايىلەرنى ئۆز ئىچىگە ئالىدۇ.","bu toplam köpligen hékayilerni öz ichige alidu."]],"吃闲饭":[["他整天在家吃闲饭，不工作。","ئۇ كۈن بويى ئۆيدە بىكار يۈرۈپ، خىزمەت قىلمايدۇ.","u kün boyi öyde bikar yürüp, xizmet qilmaydu."]],"另谋高就":[["他决定另谋高就，寻找更好的机会。","ئۇ ياخشىراق پۇرسەت ئىزدەش ئۈچۈن باشقا يەرگە ئىشلەشكە كېتىشنى قارار قىلدى.","u yaxshiraq purset izdesh üchün bashqa yerge ishleshke kétishni qarar qildi."]],"吉尔吉斯族":[["吉尔吉斯族是中亚的主要民族。","قىرغىز مىللىتى ئوتتۇرا ئاسىيانىڭ ئاساسلىق مىللىتى.","qirghiz milliti ottura asiyaning asasliq milliti."]],"吊颈":[["吊颈是一种危险的杂技动作。","ئاسما بويۇن بىر خىل خەتەرلىك ئويۇن ھەرىكىتى.","asma boyun bir xil xeterlik oyun herikiti."]],"名利场":[["名利场中充满诱惑与竞争。","نام-شۆھرەت مەيدانىدا ئازدۇرۇش ۋە رىقابەت تولۇپ تاشقان.","nam-shöhret meydanida azdurush we riqabet tolup tashqan."]],"名叫":[["这位演员名叫李华。","بۇ ئارتىسنىڭ ئىسمى لى خۇا.","bu artisning ismi li xua."]],"吧啦吧啦":[["他吧啦吧啦说个不停。","ئۇ توختىماي ۋالاڭلاپ سۆزلەۋاتىدۇ.","u toxtimay walanglap sözlewatidu."]],"含饴弄孙":[["老人含饴弄孙，尽享天伦之乐。","بوۋاي نەۋرىلىرى بىلەن ئويناپ، ئائىلە بەختىدىن ھۇزۇرلىنىۋاتىدۇ.","boway newriliri bilen oynap, aile bextidin huzurliniwatidu."]],"吴侬娇语":[["她的吴侬娇语让人如听天籁。","ئۇنىڭ ۋۇ نۇڭ يۇمشاق ئاۋازى كىشىگە سەماۋى ئاۋازدەك تۇيۇلىدۇ.","uning wu nung yumshaq awazi kishige semawi awazdek tuyulidu."]],"吴承恩":[["吴承恩是《西游记》的作者。","ۋۇ چېڭئېن «غەربكە سەپەر»نىڭ ئاپتورى.","wu chéng'én «gherbke seper»ning aptori."]],"周详":[["计划要周详一些。","پىلان تېخىمۇ ئەتراپلىق بولۇشى كېرەك.","pilan téximu etrapliq bolushi kérek."]],"哈密":[["哈密是新疆的一个城市。","خامىل شىنجاڭدىكى بىر شەھەردۇر.","xamil shinjangdiki bir sheherdur."]],"咎有应得":[["他咎有应得，因为之前太懒惰。","ئۇ ئۆزى قىلغانغا لايىق جازانى تارتىدۇ، چۈنكى ئىلگىرى بەك ھۇرۇن ئىدى.","u özi qilghangha layiq jazani tartidu, chünki ilgiri bek hurun idi."]],"咔嗒":[["门发出咔嗒一声就开了。","ئىشىك شىقىلدەپ ئېچىلىپ كەتتى.","ishik shiqildep échilip ketti."]],"告终":[["会议在热烈的掌声中告终。","يىغىن قىزغىن ئالقىش ئاۋازى ئىچىدە ئاخىرلاشتى.","yighin qizghin alqish awazi ichide axirlashti."]],"员外":[["员外家里有很多田地。","يۇەنۋەيىنىڭ ئۆيىدە نۇرغۇن يەر بار.","yuenweyining öyide nurghun yer bar."]],"品川区":[["品川区拥有众多历史悠久的景点。","چىڭاۋ رايونىدا تارىخى ئۇزۇن نۇرغۇن مەنزىرە ئورۇنلىرى بار.","chingaw rayonida tarixi uzun nurghun menzire orunliri bar."]],"嘴上没毛，办事不牢":[["年轻人嘴上没毛，办事不牢。","ياشلارنىڭ ئاغزىدا تۈك يوق، ئىش ئېتىبارسىز.","yashlarning aghzida tük yoq, ish étibarsiz."]],"单点登录":[["单点登录简化流程。","بىر نۇقتىلىق كىرىش جەرياننى ئاددىيلاشتۇرىدۇ.","bir nuqtiliq kirish jeryanni addiylashturidu."]],"嗑药":[["嗑药会对身体造成严重危害。","ناركوتىك ماددا ئىشلىتىش بەدەنگە ئېغىر زىيان يەتكۈزىدۇ.","narkotik madda ishlitish bedenge éghir ziyan yetküzidu."]],"因斯布鲁克":[["因斯布鲁克是奥地利的一座城市。","ئىنسبرۇك ئاۋسترىيەدىكى بىر شەھەر.","insbruk awstriyediki bir sheher."]],"四边":[["桌子的四边都是光滑的木质。","ئۈستەلنىڭ تۆت تەرىپى سىلىق ياغاچتىن ياسالغان.","üstelning töt teripi siliq yaghachtin yasalghan."]],"回拜":[["节日里，人们会回拜亲友。","بايرامدا كىشىلەر تۇغقانلىرىغا قايتا سالامغا بارىدۇ.","bayramda kishiler tughqanlirigha qayta salamgha baridu."]],"国子监":[["国子监是古代最高学府的象征。","دۆلەت ئىلمى ئۆگىنىش ئورگىنى قەدىمكى زاماندىكى ئەڭ يۇقىرى ئوقۇش يۇرتىنىڭ سىمۋولى.","dölet ilmi öginish orgini qedimki zamandiki eng yuqiri oqush yurtining simwoli."]],"国字脸":[["他拥有典型的国字脸，十分帅气。","ئۇنىڭدا تىپىك دۆلەت خېتى شەكلىدىكى چىرايى بار، ئىنتايىن كېلىشكەن.","uningda tipik dölet xéti sheklidiki chirayi bar, intayin kélishken."]],"圆规":[["圆规是作图的重要工具。","پەرگار سىزىش ئىشلىرىدىكى مۇھىم قورالدۇر.","pergar sizish ishliridiki muhim qoraldur."]],"国际刑事警察组织":[["国际刑事警察组织协助跨国执法。","خەلقئارا جىنايى ساقچى تەشكىلاتى دۆلەتلەر ئارا قانۇن ئىجرا قىلىشقا ياردەم بېرىدۇ.","xelq'ara jinayi saqchi teshkilati döletler ara qanun ijra qilishqa yardem béridu."]],"土豆泥":[["土豆泥口感细腻，适合搭配肉类。","توپا يۇمۇرغا ئېغىزى نەپىس، گۆش بىلەن بىرلەشتۈرۈشكە ماس كېلىدۇ.","topa yumurgha éghizi nepis, gösh bilen birleshtürüshke mas kélidu."]],"坡县":[["坡县是新加坡的旧称。","پو شيەن سىنگاپورنىڭ كونا نامى.","po shyen singaporning kona nami."]],"坡鹿":[["坡鹿是一种生活在山区的鹿类动物。","پو بۇغىسى تاغلىق رايوندا ياشايدىغان بىر خىل بۇغا تۈرى.","po bughisi taghliq rayonda yashaydighan bir xil bugha türi."]],"埇桥":[["埇桥是安徽省的一个著名地区。","يۇڭچياۋ ئەنخۇي ئۆلكىسىدىكى مەشھۇر بىر رايون.","yungchyaw enxuy ölkisidiki meshhur bir rayon."]],"坎培拉":[["坎培拉是澳大利亚的首都。","كانبېررا ئاۋسترالىيەنىڭ پايتەختى.","kanbérra awstraliyening paytexti."]],"培林":[["这家公司的培林部门负责员工培训。","بۇ شىركەتنىڭ پەيلىن بۆلۈمى خىزمەتچىلەرنى تەربىيىلەشكە مەسئۇل.","bu shirketning peylin bölümi xizmetchilerni terbiyileshke mes'ul."]],"地皮":[["地皮的价格近年来持续上涨。","يەر باھاسى يېقىنقى يىللاردا داۋاملىق ئۆرلەپ كەلدى.","yer bahasi yéqinqi yillarda dawamliq örlep keldi."]],"地藏菩萨":[["地藏菩萨在佛教中备受尊敬。","دىزاڭ بۇددا بۇتپەرەسلىكتە ئىنتايىن ھۆرمەتكە سازاۋەر.","dizang budda butpereslikte intayin hörmetke sazawer."]],"基甸":[["基甸是以色列古代的一位著名领袖。","گىدېئون ئىسرائىلنىڭ قەدىمكى دەۋرىدىكى داڭلىق بىر رەھبەردۇر.","gidéon israilning qedimki dewridiki dangliq bir rehberdur."]],"塞纳河":[["塞纳河是法国北部的一条重要河流。","سېنا دەرياسى فرانسىيەنىڭ شىمالىدىكى مۇھىم بىر دەريا.","séna deryasi fransiyening shimalidiki muhim bir derya."]],"墨玉县":[["墨玉县出产优质的和田玉。","مويۈ ناھىيىسى سۈپەتلىك خوتەن قاشتېشى ئىشلەپچىقىرىدۇ.","moyü nahiyisi süpetlik xoten qashtéshi ishlepchiqiridu."]],"压舌板":[["医生用压舌板检查喉咙。","دوختۇر تىل بېسىقۇچ بىلەن گالنى تەكشۈردى.","doxtur til bésiquch bilen galni tekshürdi."]],"外埔":[["外埔是台湾的一个小镇。","ۋەيپۇ تەيۋەندىكى بىر كىچىك بازىرى.","weypu teywendiki bir kichik baziri."]],"大氅":[["他披着一件黑色大氅。","ئۇ قارا چوڭ چاپان كىيىۋالغان.","u qara chong chapan kiyiwalghan."]],"外胚层":[["胚胎发育时，外胚层会形成皮肤和神经系统。","ئېمبىرىيون تەرەققىياتىدا، تاشقى ئېمبىرىيون قەۋىتى تېرە ۋە نېرۋا سىستېمىسىنى شەكىللەندۈرىدۇ.","émbiriyon tereqqiyatida, tashqi émbiriyon qewiti tére we nérwa sistémisini shekillendüridu."]],"大清":[["大清王朝统治了中国两百年。","چىڭ سۇلالىسى جۇڭگونى ئىككى يۈز يىل باشقۇردى.","ching sulalisi junggoni ikki yüz yil bashqurdi."]],"多普勒":[["多普勒效应与波的频率变化有关。","دوپلېر ئېففېكتى دولقۇن چاستوتىسىنىڭ ئۆزگىرىشى بىلەن مۇناسىۋەتلىك.","doplér éffékti dolqun chastotisining özgirishi bilen munasiwetlik."]],"大姐大":[["她是我们团队的大姐大。","ئۇ بىزنىڭ گۇرۇپپىمىزنىڭ ئاچىسى.","u bizning guruppimizning achisi."]],"大锅":[["大锅适合煮一大锅汤。","چوڭ قازان چوڭ قازان شورپا قاينىتىشقا ماس كېلىدۇ.","chong qazan chong qazan shorpa qaynitishqa mas kélidu."]],"大限到来":[["大限到来，无法逃避。","ئۆلۈم ۋاقتى يېتىپ كەلدى، قېچىپ قۇتۇلغىلى بولمايدۇ.","ölüm waqti yétip keldi, qéchip qutulghili bolmaydu."]],"大雅":[["他的举止非常大雅。","ئۇنىڭ ئەدەپ-ئەخلاقى ئىنتايىن نەپىس.","uning edep-exlaqi intayin nepis."]],"大斋节":[["大斋节有许多传统习俗。","چوڭ روزىدا نۇرغۇن ئەنئەنىۋى ئادەتلەر بار.","chong rozida nurghun en'eniwi adetler bar."]],"天旋地转":[["他感到天旋地转，头晕目眩。","ئۇنىڭ بېشى ئايلانغاندەك، كۆزى قاراڭغۇلاشقاندەك بولدى.","uning béshi aylanghandek, közi qarangghulashqandek boldi."]],"大病":[["他因突发大病而住院治疗。","ئۇ تۇيۇقسىز ئېغىر كېسەلگە گىرىپتار بولۇپ دوختۇرخانىدا داۋالاندى.","u tuyuqsiz éghir késelge giriptar bolup doxturxanida dawalandi."]],"天平动":[["天平动是钟摆的周期性运动。","تەڭپۇڭلۇق ھەرىكىتى سائەت مېخانىزمىنىڭ دەۋرىي ھەرىكىتىدۇر.","tengpungluq herikiti saet méxanizmining dewriy herikitidur."]],"天机不可泄漏":[["天机不可泄漏，否则会招来灾祸。","تەقدىر سىرىنى ئاشكارىلىغىلى بولمايدۇ، بولمىسا ئاپەت كېلىدۇ.","teqdir sirini ashkarilighili bolmaydu, bolmisa apet kélidu."]],"天璇":[["天璇是天琴座的主星。","تيەنشۈەن لىرا يۇلتۇز تۈركۈمىنىڭ ئاساسلىق يۇلتۇزىدۇر.","tyenshüen lira yultuz türkümining asasliq yultuzidur."]],"天皇":[["天皇是日本古代的最高统治者。","تيەنخۇاڭ ياپونىيەنىڭ قەدىمكى زاماندىكى ئەڭ يۇقىرى ھۆكۈمرانىدۇر.","tyenxuang yaponiyening qedimki zamandiki eng yuqiri hökümranidur."]],"太白山":[["太白山是中国西北部的著名山脉。","تەيبەي تېغى جۇڭگونىڭ شىمالىي غەربىدىكى مەشھۇر تاغ تىزمىسى.","teybey téghi junggoning shimaliy gherbidiki meshhur tagh tizmisi."]],"失序":[["会场秩序失序，难以控制。","يىغىن مەيدانىنىڭ تەرتىپى بۇزۇلدى، كونترول قىلىش قىيىن بولدى.","yighin meydanining tertipi buzuldi, kontrol qilish qiyin boldi."]],"失意":[["这次考试让他感到十分失意。","بۇ ئىمتىھان ئۇنى بەك رۇھىي چۈشكۈنلۈككە گىرىپتار قىلدى.","bu imtihan uni bek ruhiy chüshkünlükke giriptar qildi."]],"大惊小怪":[["这点小事何必大惊小怪？","بۇنداق كىچىك ئىشقا نېمىشقا ھەيران قالىسىز؟","bundaq kichik ishqa némishqa heyran qalisiz?"]],"大体上":[["大体上这个方案是可行的。","ئومۇمەن بۇ پىلان ئەمەلىيلەشتۈرگىلى بولىدۇ.","omumen bu pilan emeliyleshtürgili bolidu."]],"奏鸣曲":[["贝多芬的《月光》是一首著名的奏鸣曲。","بېتخوۋېننىڭ «ئاي نۇرى» ئاتلىق ئەسىرى داڭلىق بىر سوناتا.","bétxowénning «ay nuri» atliq esiri dangliq bir sonata."]],"天镇":[["这座小镇被称为天镇。","بۇ كىچىك بازىرى تەڭرى بازىرى دەپ ئاتىلىدۇ.","bu kichik baziri tengri baziri dep atilidu."]],"奥林匹克运动会":[["奥林匹克运动会每四年举办一次。","ئولىمپىيادا تەنتەربىيە مۇسابىقىسى ھەر تۆت يىلدا بىر قېتىم ئۆتكۈزۈلىدۇ.","olimpiyada tenterbiye musabiqisi her töt yilda bir qétim ötküzülidu."]],"奶头":[["这个奶头有点硬。","بۇ ئەمچەك بىر ئاز قاتتىق.","bu emchek bir az qattiq."]],"好兵帅克":[["《好兵帅克》是一部经典小说。","«ياخشى ئەسكەر شۋېيك» كلاسسىك رومان.","«yaxshi esker shwéyk» klassik roman."]],"妖气":[["房间里弥漫着妖气。","ئۆيدە جادۇگەرلىك ھىدى تارقالدى.","öyde jadugerlik hidi tarqaldi."]],"妖魔":[["妖魔横行，百姓苦不堪言。","جادۇگەرلەر ھۆكۈم سۈرۈپ، خەلق ئازاب چەكتى.","jadugerler höküm sürüp, xelq azab chekti."]],"妄求":[["他妄求不切实际的目标，终无所获。","ئۇ ئەمەلىيەتكە ئۇيغۇن بولمىغان نىشانلارنى ئاساسسىز تىلەپ، ئاخىرى ھېچ نەرسىگە ئېرىشەلمىدى.","u emeliyetke uyghun bolmighan nishanlarni asassiz tilep, axiri héch nersige érishelmidi."]],"妨碍球":[["这个动作被裁判判为妨碍球。","بۇ ھەرىكەتنى تۆۋەنچى «توپقا دەخلى» دەپ ھۆكۈم قىلدى.","bu heriketni töwenchi «topqa dexli» dep höküm qildi."]],"姊丈":[["姊丈对我很关照。","يەزنەم ماڭا ئىنتايىن كۆيۈمچان.","yeznem manga intayin köyümchan."]],"如胶似漆":[["他们如胶似漆，形影不离。","ئۇلار چاپلىشىپ يېپىشقاندەك، ھەرگىز ئايرىلمايدۇ.","ular chapliship yépishqandek, hergiz ayrilmaydu."]],"姿态婀娜":[["她舞姿姿态婀娜。","ئۇنىڭ ئۇسسۇل ھەرىكىتى ناھايىتى گۈزەل.","uning ussul herikiti nahayiti güzel."]],"侄孙女":[["侄孙女特别喜欢画画。","جىيەنسۈنقىز رەسىم سىزىشقا ئالاھىدە ئامراق.","jiyensünqiz resim sizishqa alahide amraq."]],"姑息":[["不能姑息这种错误行为。","بۇنداق خاتا قىلمىشقا يول قويۇشقا بولمايدۇ.","bundaq xata qilmishqa yol qoyushqa bolmaydu."]],"媒材":[["艺术家选择合适的媒材进行创作。","سەنئەتكار ئىجادىيەت ئۈچۈن مۇۋاپىق ۋاسىتە تاللايدۇ.","sen'etkar ijadiyet üchün muwapiq wasite tallaydu."]],"存取":[["存取操作需要时间。","ساقلاش-ئېلىش مەشغۇلاتى ۋاقىت تەلەپ قىلىدۇ.","saqlash-élish meshghulati waqit telep qilidu."]],"子母炸弹":[["子母炸弹在爆炸时会产生多个子弹头。","ئانا-بالا بومبىسى پارتلىغاندا كۆپلىگەن ئوق بېشىنى ھاسىل قىلىدۇ.","ana-bala bombisi partlighanda köpligen oq béshini hasil qilidu."]],"孟良崮":[["孟良崮战役是解放战争的重要战役。","مېڭلياڭگۇ جېڭى ئازادلىق ئۇرۇشىدىكى مۇھىم جەڭ.","ménglyanggu jéngi azadliq urushidiki muhim jeng."]],"守分":[["他守分守己，不越雷池一步。","ئۇ ئۆز ئورنىدا تۇرۇپ، ھېچقانداق چەكتىن ئاشمايدۇ.","u öz ornida turup, héchqandaq chektin ashmaydu."]],"安纳波利斯":[["安纳波利斯是美国马里兰州的一座城市。","ئانناپولىس ئامېرىكىنىڭ مارىلاند شتاتىدىكى بىر شەھەر.","annapolis amérikining mariland shtatidiki bir sheher."]],"宣威":[["宣威的美食很有特色。","شۈەنۋېي تائاملىرى ئىنتايىن ئالاھىدىە.","shüenwéy taamliri intayin alahidie."]],"宣传画":[["宣传画生动展现了环保理念。","تەشۋىقات رەسىمى مۇھىت ئاسراش ئىدىيەسىنى جانلىق نامايان قىلدى.","teshwiqat resimi muhit asrash idiyesini janliq namayan qildi."]],"定于一尊":[["他定于一尊，不容异议。","ئۇ بىرلا ئورۇنغا بېكىتىلدى، باشقا پىكىرگە يول قويۇلمايدۇ.","u birla orungha békitildi, bashqa pikirge yol qoyulmaydu."]],"容受":[["他能够容受不同的意见。","ئۇ ئوخشىمىغان پىكىرلەرنى كۆتۈرەلەيدۇ.","u oxshimighan pikirlerni kötüreleydu."]],"密歇根湖":[["密歇根湖是北美最大的淡水湖。","مىچىگان كۆلى شىمالىي ئامېرىكىدىكى ئەڭ چوڭ تاتلىق سۇ كۆلىدۇر.","michigan köli shimaliy amérikidiki eng chong tatliq su kölidur."]],"密西根州":[["密西根州拥有众多知名大学。","مىچىگان شتاتىدا نۇرغۇن داڭلىق ئۇنىۋېرسىتېتلار بار.","michigan shtatida nurghun dangliq uniwérsitétlar bar."]],"宁江":[["宁江是一条重要的河流。","نىڭجياڭ مۇھىم بىر دەريا.","ningjyang muhim bir derya."]],"察哈尔右翼前旗":[["察哈尔右翼前旗以畜牧业闻名。","چاقار يېزىقى ئالدىنقى بايرىقى چارۋىچىلىق بىلەن داڭلىق.","chaqar yéziqi aldinqi bayriqi charwichiliq bilen dangliq."]],"宝坻":[["宝坻是天津的一个区。","باۋدى تيەنجىننىڭ بىر رايونى.","bawdi tyenjinning bir rayoni."]],"富于想像":[["他的创作富于想像力。","ئۇنىڭ ئىجادىيىتى تەسەۋۋۇرغا باي.","uning ijadiyiti tesewwurgha bay."]],"家暴":[["家暴行为必须受到法律的严厉制裁。","ئائىلە زوراۋانلىقى قىلمىشى چوقۇم قانۇننىڭ قاتتىق جازاسىغا ئۇچرىشى كېرەك.","aile zorawanliqi qilmishi choqum qanunning qattiq jazasigha uchrishi kérek."]],"寸口脉":[["寸口脉象反映了身体的健康状况。","بىلەك تومۇرىنىڭ ئەھۋالى بەدەننىڭ ساغلاملىق ئەھۋالىنى ئەكس ئەتتۈرىدۇ.","bilek tomurining ehwali bedenning saghlamliq ehwalini eks ettüridu."]],"封土":[["这片封土是古代贵族的领地。","بۇ پېچەتلەنگەن زېمىن قەدىمكى زاماندىكى ئاقسۆڭەكلەرنىڭ يېرى ئىدى.","bu péchetlengen zémin qedimki zamandiki aqsöngeklerning yéri idi."]],"尊师":[["尊师是对老师的敬称。","زۇنشى ئوقۇتقۇچىغا قىلىنغان ھۆرمەتلىك ئاتالغۇ.","zunshi oqutquchigha qilinghan hörmetlik atalghu."]],"对空火器":[["这种对空火器能有效拦截无人机。","بۇ خىل ھاۋاغا قارىتىلغان ئوت ئالغۇچ ئۇچقۇسىز ئايروپىلانلارنى ئۈنۈملۈك توسالايدۇ.","bu xil hawagha qaritilghan ot alghuch uchqusiz ayropilanlarni ünümlük tosalaydu."]],"小恭":[["小恭是古代对上厕所的谦称。","كىچىك گۇڭ قەدىمكى زاماندا ھاجەتخانىغا بارىدىغانلىقنىڭ كەمتەرلىك ئاتىلىشى.","kichik gung qedimki zamanda hajetxanigha baridighanliqning kemterlik atilishi."]],"小时工":[["这家餐厅招聘小时工。","بۇ رېستوران كىچىك ۋاقىتلىق ئىشچى تەكلىپ قىلىدۇ.","bu réstoran kichik waqitliq ishchi teklip qilidu."]],"尺寸过大":[["这个箱子尺寸过大，无法携带。","بۇ قۇتا ئۆلچىمى بەك چوڭ، ئېلىپ ماڭغىلى بولمايدۇ.","bu quta ölchimi bek chong, élip mangghili bolmaydu."]],"尼人":[["尼人属于古代的人类族群。","نىئاندرتال ئادەم قەدىمكى ئىنسان توپىغا تەۋە.","niandrtal adem qedimki insan topigha tewe."]],"尖锐湿疣":[["尖锐湿疣是一种常见的性传播疾病。","ئۆتكۈر سۆگەل جىنسىي يول بىلەن يۇقىدىغان كۆپ ئۇچرايدىغان كېسەللىك.","ötkür sögel jinsiy yol bilen yuqidighan köp uchraydighan késellik."]],"展平":[["他展平地图仔细查看。","ئۇ خەرىتىنى يېيىپ ئەستايىدىل قارىدى.","u xeritini yéyip estayidil qaridi."]],"尾翼":[["飞机的尾翼提供稳定性。","ئايروپىلاننىڭ قۇيرۇق قانىتى مۇقىملىق بىلەن تەمىنلەيدۇ.","ayropilanning quyruq qaniti muqimliq bilen teminleydu."]],"山苏":[["山苏是一种具有药用价值的植物。","تاغ سۇسى دورىلىق قىممەتكە ئىگە بولغان بىر خىل ئۆسۈملۈكتۇر.","tagh susi doriliq qimmetke ige bolghan bir xil ösümlüktur."]],"山榄科":[["山榄科包含许多热带植物。","شاڭلانكە ئائىلىسى كۆپلىگەن تروپىك ئۆسۈملۈكلەرنى ئۆز ئىچىگە ئالىدۇ.","shanglanke ailisi köpligen tropik ösümlüklerni öz ichige alidu."]],"屯戍":[["古代军队常屯戍于边境以抵御外敌。","قەدىمكى قوشۇنلار دائىم چېگرا رايونىدا تۇن ئەسكەرلىك قىلىپ، سىرتقى دۈشمەنگە تاقابىل تۇراتتى.","qedimki qoshunlar daim chégra rayonida tun eskerlik qilip, sirtqi düshmenge taqabil turatti."]],"居正":[["居正是一位历史人物。","جۇجېڭ تارىخىي شەخس.","jujéng tarixiy shexs."]],"岸然":[["他岸然地站在岸边。","ئۇ قىرغاقتا تەكشەيىپ قىرغاق بويىدا تۇرۇپتۇ.","u qirghaqta teksheyip qirghaq boyida turuptu."]],"岐山县":[["岐山县位于陕西省中部。","چىشەن ناھىيىسى شەنشى ئۆلكىسىنىڭ ئوتتۇرىسىدا جايلاشقان.","chishen nahiyisi shenshi ölkisining otturisida jaylashqan."]],"布莱克史密斯":[["布莱克史密斯是一位著名的铁匠。","بلاكسىمىس مەشھۇر بىر تۆمۈرچىدۇر.","blaksimis meshhur bir tömürchidur."]],"巴布延群岛":[["巴布延群岛是菲律宾的一部分。","بابۇيان تاقىم ئاراللىرى فىلىپپىننىڭ بىر قىسمى.","babuyan taqim aralliri filippinning bir qismi."]],"帕劳":[["帕劳是一个美丽的太平洋岛国。","پالاۋ گۈزەل بىر تىنچ ئوكيان ئارال دۆلىتىدۇر.","palaw güzel bir tinch okyan aral dölitidur."]],"布里特妮":[["布里特妮是一位著名的流行歌手。","بۇرىتتىنى داڭلىق بىر ئاممىباب ناخشىچىدۇر.","burittini dangliq bir ammibab naxshichidur."]],"布雷斯特":[["布雷斯特是法国西部的一座城市。","برېست فرانسىيەنىڭ غەربىدىكى بىر شەھەردۇر.","brést fransiyening gherbidiki bir sheherdur."]],"巴士底":[["巴士底狱是法国历史上的著名监狱。","باستىلىيە فرانسىيە تارىخىدىكى مەشھۇر تۈرمە.","bastiliye fransiye tarixidiki meshhur türme."]],"常委会":[["常委会负责处理紧急的行政事务。","دائىمىي كومىتېت جىددىي مەمۇرىي ئىشلارنى بىر تەرەپ قىلىشقا مەسئۇل.","daimiy komitét jiddiy memuriy ishlarni bir terep qilishqa mes'ul."]],"平滑":[["皮肤光滑细腻，看起来非常平滑。","تېرىسى سىلىق ۋە نەپىس، ئىنتايىن تەكشى كۆرۈنىدۇ.","térisi siliq we nepis, intayin tekshi körünidu."]],"康康舞":[["康康舞是一种流行的舞蹈。","كانكان ئۇسسۇلى بىر خىل مودا ئۇسسۇلدۇر.","kankan ussuli bir xil moda ussuldur."]],"库克船长":[["库克船长是著名的英国航海家。","كاپىتان كۇك داڭلىق ئەنگلىيە دېڭىز سەپىرىچىسىدۇر.","kapitan kuk dangliq engliye déngiz sepirichisidur."]],"平阴县":[["平阴县拥有悠久的玫瑰种植历史。","پىڭيىن ناھىيىسى ئۇزۇن تارىخلىق ئەتىرگۈل تېرىش تارىخىغا ئىگە.","pingyin nahiyisi uzun tarixliq etirgül térish tarixigha ige."]],"厂址":[["厂址位于城市的工业区。","زاۋۇت ئورنى شەھەرنىڭ سانائەت رايونىدا جايلاشقان.","zawut orni sheherning sanaet rayonida jaylashqan."]],"广九":[["广九铁路连接广州与九龙。","گۇاڭجۇ-كاۋلۇن تۆمۈر يولى گۇاڭجۇ بىلەن كاۋلۇننى تۇتاشتۇرىدۇ.","guangju-kawlun tömür yoli guangju bilen kawlunni tutashturidu."]],"广域网路":[["广域网路的维护需要专业技术人员操作。","كەڭ دائىرىلىك تور يولىنىڭ ئاسراشى كەسپىي تېخنىك خادىملارنىڭ مەشغۇلات قىلىشىنى تەلەپ قىلىدۇ.","keng dairilik tor yolining asrashi kespiy téxnik xadimlarning meshghulat qilishini telep qilidu."]],"广安门":[["广安门是北京著名的历史古迹之一。","گۇئەنمېن بېيجىڭنىڭ مەشھۇر تارىخىي قەدىمكى ئىزلىرىنىڭ بىرىدۇر.","guenmén béyjingning meshhur tarixiy qedimki izlirining biridur."]],"弄堂":[["这条弄堂里住满了老住户。","بۇ كوچىدا كونا ئاھالىلەر تولۇپ ياشايدۇ.","bu kochida kona ahaliler tolup yashaydu."]],"弄懂":[["他终于弄懂了这道题。","ئۇ ئاخىرى بۇ مەسىلىنى چۈشەندى.","u axiri bu mesilini chüshendi."]],"廷试":[["廷试是古代皇帝主持的最高科举考试。","تىڭشى قەدىمدە ئىمپېراتور رىياسەتچىلىك قىلغان ئەڭ يۇقىرى دەرىجىلىك ئىمتىھان.","tingshi qedimde impérator riyasetchilik qilghan eng yuqiri derijilik imtihan."]],"张飞":[["张飞是三国时期的名将。","جياڭ فېي ئۈچ پادىشاھلىق دەۋرىدىكى داڭلىق سەركەردە.","jyang féy üch padishahliq dewridiki dangliq serkerde."]],"张骞":[["张骞是丝绸之路的开拓者。","جياڭ چيەن يىپەك يولىنىڭ ئاچقۇچىسى.","jyang chyen yipek yolining achquchisi."]],"张自烈":[["张自烈是晚清时期的官员。","جاڭ زىلىيە چىڭ سۇلالىسىنىڭ ئاخىرقى مەزگىلىدىكى ئەمەلدار.","jang ziliye ching sulalisining axirqi mezgilidiki emeldar."]],"引决":[["他最终引决了多年的犹豫。","ئۇ ئاخىرىدا يىللارچە ئىككىلەنگەنلىكىنى ھەل قىلدى.","u axirida yillarche ikkilengenlikini hel qildi."]],"引河":[["引河工程改变了当地的地形。","سۇ ئېلىپ كېلىش قۇرۇلۇشى يەرلىك يەر شەكلىنى ئۆزگەرتتى.","su élip kélish qurulushi yerlik yer sheklini özgertti."]],"引火柴":[["这种引火柴能迅速点燃木材。","بۇ خىل ئوت ياققۇچ ياغاچنى تېز ئوت ئالدۇرىدۇ.","bu xil ot yaqquch yaghachni téz ot alduridu."]],"弦乐器":[["小提琴是一种弦乐器。","كىچىك سكرىپكا بىر خىل تارلىق چالغۇدۇر.","kichik skripka bir xil tarliq chalghudur."]],"弦而鼓之":[["弦而鼓之，声传千里。","تارنى چېلىپ، ئاۋازى مىڭ چاقىرىمغا يېتىدۇ.","tarni chélip, awazi ming chaqirimgha yétidu."]],"后半场":[["后半场比赛异常激烈。","كېيىنكى يېرىم مەيداندىكى مۇسابىقە ئىنتايىن كەسكىن بولدى.","kéyinki yérim meydandiki musabiqe intayin keskin boldi."]],"形象代言人":[["这位明星是某品牌的形象代言人。","بۇ يۇلتۇز مەلۇم بىر ماركىنىڭ ئوبراز ۋەكىلىدۇر.","bu yultuz melum bir markining obraz wekilidur."]],"德智体美":[["学校注重德智体美全面发展。","مەكتەپ ئەخلاق، ئەقىل، جىسمانىي ۋە ئەستېتىك جەھەتلەردىن ئومۇميۈزلۈك تەرەققىي قىلىشقا ئەھمىيەت بېرىدۇ.","mektep exlaq, eqil, jismaniy we estétik jehetlerdin omumyüzlük tereqqiy qilishqa ehmiyet béridu."]],"心计":[["他的心计令人防不胜防。","ئۇنىڭ كۆڭۈل ھىيلىسىدىن ساقلىنىش تەس.","uning köngül hiylisidin saqlinish tes."]],"思想体系":[["他建立了一套完整的思想体系。","ئۇ تولۇق بىر ئىدىيە سىستېمىسىنى قۇردى.","u toluq bir idiye sistémisini qurdi."]],"恩仇":[["恩仇交织，难以割舍。","مەرھەمەت بىلەن ئۆچمەنلىك ئارىلاشقان بولۇپ، ئايرىۋېتىش قىيىن.","merhemet bilen öchmenlik arilashqan bolup, ayriwétish qiyin."]],"急转直下":[["他的成绩急转直下，令人担忧。","ئۇنىڭ نەتىجىسى تۇيۇقسىز تۆۋەنلەپ، كىشىنى ئەندىشىگە سالدى.","uning netijisi tuyuqsiz töwenlep, kishini endishige saldi."]],"恼人":[["这个问题真让人恼人。","بۇ مەسىلە ھەقىقەتەن كىشىنى بىئارام قىلىدۇ.","bu mesile heqiqeten kishini biaram qilidu."]],"惠州":[["惠州是一座历史悠久的城市。","خۇيجۇ ئۇزۇن تارىخقا ئىگە بىر شەھەر.","xuyju uzun tarixqa ige bir sheher."]],"悟能":[["悟能就是猪八戒的本名。","ۋۇنېڭ دېگەن چوڭ توڭگۇز سەككىزنىڭ ئەسلى ئىسمى.","wunéng dégen chong tongguz sekkizning esli ismi."]],"爱意":[["他的眼神中充满了深深的爱意。","ئۇنىڭ كۆزلىرىدە چوڭقۇر مېھىر-مۇھەببەت تولۇپ تۇرۇپتۇ.","uning közliride chongqur méhir-muhebbet tolup turuptu."]],"想也没想":[["他冲上去，想也没想。","ئۇ ئويلاپمۇ باقماي ئالدىغا ئېتىلىپ چىقتى.","u oylapmu baqmay aldigha étilip chiqti."]],"懂局":[["他完全懂局里的规矩。","ئۇ ئىدارىنىڭ قائىدىلىرىنى تولۇق چۈشىنىدۇ.","u idarining qaidilirini toluq chüshinidu."]],"懒得搭理":[["我懒得搭理他。","مەن ئۇنىڭغا قۇلاق سالغۇم يوق.","men uninggha qulaq salghum yoq."]],"憎厌":[["他对这种虚伪的社交活动感到极度憎厌。","ئۇ بۇنداق ساختىپەزلىك ئىجتىمائىي پائالىيەتلەردىن ئىنتايىن يىرگىنىدۇ.","u bundaq saxtipezlik ijtimaiy paaliyetlerdin intayin yirginidu."]],"成华":[["成华是成都的一个老城区。","چېڭخۇا چېڭدۇنىڭ بىر كونا شەھەر رايونى.","chéngxua chéngduning bir kona sheher rayoni."]],"戊午":[["戊午年是中国传统纪年法。","پېنتاۋ يىلى جۇڭگونىڭ ئەنئەنىۋى يىل ھېسابلاش ئۇسۇلى.","péntaw yili junggoning en'eniwi yil hésablash usuli."]],"戊戌维新":[["戊戌维新是一场短暂的改革运动。","پېنتاۋ ئىسلاھاتى قىسقا مۇددەتلىك بىر ئىسلاھات ھەرىكىتى ئىدى.","péntaw islahati qisqa muddetlik bir islahat herikiti idi."]],"戕害":[["这种不良习惯正在戕害他的健康。","بۇ يامان ئادەت ئۇنىڭ ساغلاملىقىغا زىيان يەتكۈزمەكتە.","bu yaman adet uning saghlamliqigha ziyan yetküzmekte."]],"戏剧家":[["这位戏剧家创作了许多经典作品。","بۇ تىياتىرچى نۇرغۇن كلاسسىك ئەسەرلەرنى ئىجاد قىلدى.","bu tiyatirchi nurghun klassik eserlerni ijad qildi."]],"戒子":[["戒子是一种用于约束行为的古代工具。","چەكلەش ئەسۋابى قەدىمكى زاماندا ھەرىكەتنى چەكلەش ئۈچۈن ئىشلىتىلگەن قورال ئىدى.","cheklesh eswabi qedimki zamanda heriketni cheklesh üchün ishlitilgen qoral idi."]],"戳脊梁骨":[["他被人戳脊梁骨说闲话。","ئۇنىڭ كەينىدىن گەپ قىلىپ پاراكەندە قىلىشتى.","uning keynidin gep qilip parakende qilishti."]],"戈氏岩鹀":[["戈氏岩鹀是濒危的鸟类。","گوبى تاغ تورغىسى خەتەر ئاستىدىكى قۇش تۈرىدۇر.","gobi tagh torghisi xeter astidiki qush türidur."]],"恋物":[["他对某些物品有恋物倾向。","ئۇنىڭ بەزى بۇيۇملارغا نەرسىگە كۆڭۈل باغلاش مايىللىقى بار.","uning bezi buyumlargha nersige köngül baghlash mayilliqi bar."]],"才华出众":[["他的才华出众，备受瞩目。","ئۇنىڭ تالانتى ئالاھىدە بولۇپ، كۆپچىلىكنىڭ دىققىتىنى تارتقان.","uning talanti alahide bolup, köpchilikning diqqitini tartqan."]],"手无寸铁":[["他们手无寸铁，无法抵抗。","ئۇلار قورالسىز، قارشىلىق كۆرسىتەلمەيدۇ.","ular qoralsiz, qarshiliq körsitelmeydu."]],"打保票":[["我打保票，他一定会来。","مەن كاپالەت بېرىمەن، ئۇ چوقۇم كېلىدۇ.","men kapalet bérimen, u choqum kélidu."]],"打哑谜":[["他在打哑谜。","ئۇ تېپىشماق ئوينىماقتا.","u tépishmaq oynimaqta."]],"托塔天王":[["托塔天王是神话人物。","توتا تەڭرىسى ئەپسانىۋى شەخستۇر.","tota tengrisi epsaniwi shexstur."]],"戎行":[["戎行指军队或军事行动。","جاڭ خاڭ ئارمىيە ياكى ھەربىي ھەرىكەتنى كۆرسىتىدۇ.","jang xang armiye yaki herbiy heriketni körsitidu."]],"批斗":[["批斗大会旨在揭露错误思想。","تەنقىد يىغىنى خاتا ئىدىيەنى ئاشكارىلاشنى مەقسەت قىلغان.","tenqid yighini xata idiyeni ashkarilashni meqset qilghan."]],"把守":[["士兵们严把守重要关卡。","ئەسكەرلەر مۇھىم ئۆتكەلنى قاتتىق قوغدايدۇ.","eskerler muhim ötkelni qattiq qoghdaydu."]],"抓地力":[["轮胎的抓地力直接影响驾驶安全。","چاقچاقنىڭ يەر تۇتۇش كۈچى ماشىنا ھەيدەش بىخەتەرلىكىگە بىۋاسىتە تەسىر كۆرسىتىدۇ.","chaqchaqning yer tutush küchi mashina heydesh bixeterlikige biwasite tesir körsitidu."]],"拉丁化":[["拉丁化促进了文字改革。","لاتىنلاشتۇرۇش يېزىق ئىسلاھاتىنى ئىلگىرى سۈردى.","latinlashturush yéziq islahatini ilgiri sürdi."]],"抗忧郁药":[["抗忧郁药需遵医嘱谨慎使用。","غەمكىنلىككە قارشى دورىلار دوختۇرنىڭ كۆرسەتمىسىگە قاتتىق ئەمەل قىلىپ ئېھتىياتچانلىق بىلەن ئىشلىتىلىشى كېرەك.","ghemkinlikke qarshi dorilar doxturning körsetmisige qattiq emel qilip éhtiyatchanliq bilen ishlitilishi kérek."]],"拉夫堡大学":[["拉夫堡大学是英国顶尖的研究型大学之一。","لافبورو ئۇنىۋېرسىتېتى ئەنگلىيەنىڭ ئالدىنقى قاتار ئۇنىۋېرسىتېتلىرىنىڭ بىرى.","lafboro uniwérsitéti engliyening aldinqi qatar uniwérsitétlirining biri."]],"抛费":[["这笔抛费实在太高了。","بۇ قوپلاش چىقىمى ھەقىقەتەن بەك يۇقىرى.","bu qoplash chiqimi heqiqeten bek yuqiri."]],"投影机":[["这台投影机画质清晰。","بۇ پرويېكتورنىڭ سۈرەت سۈپىتى ئېنىق.","bu proyéktorning süret süpiti éniq."]],"拼刺":[["士兵们在战场上进行拼刺训练。","ئەسكەرلەر سەھرە مەيدانىدا بىگىز سانجىش مەشىقى ئېلىپ بارماقتا.","eskerler sehre meydanida bigiz sanjish meshiqi élip barmaqta."]],"拼死拼活":[["他们拼死拼活才完成项目。","ئۇلار جان-جەھلى بىلەن تىرىشىپ ئاندىن تۈرنى تاماملىدى.","ular jan-jehli bilen tiriship andin türni tamamlidi."]],"指斥":[["他指斥了同事的不当行为。","ئۇ خىزمەتداشلىرىنىڭ نامۇۋاپىق قىلمىشلىرىنى ئەيىبلىدى.","u xizmetdashlirining namuwapiq qilmishlirini eyiblidi."]],"捐税":[["捐税是国家的重要收入。","باج-سېلىق دۆلەتنىڭ مۇھىم كىرىمىدۇر.","baj-séliq döletning muhim kirimidur."]],"舍身":[["他舍身救人，令人敬佩。","ئۇ جانىنى پىدا قىلىپ كىشىلەرنى قۇتقۇزدى، بۇ كىشىلەرنى ھەيران قالدۇردى.","u janini pida qilip kishilerni qutquzdi, bu kishilerni heyran qaldurdi."]],"排水渠":[["雨水流入排水渠。","يېغىن سۈيى سۇ چىقىرىش ئۆستىڭىگە ئېقىپ كىرىدۇ.","yéghin süyi su chiqirish östingige éqip kiridu."]],"揄袂":[["他揄袂展示华丽的衣袖。","ئۇ يەڭلىرىنى كۆتۈرۈپ ھەشەمەتلىك يەڭلىرىنى كۆرسەتتى.","u yenglirini kötürüp heshemetlik yenglirini körsetti."]],"挺尸":[["他躺在地上挺尸。","ئۇ يەردە ئۆلۈك يېتىپتۇ.","u yerde ölük yétiptu."]],"挽力":[["他的挽力足以支撑整个装置。","ئۇنىڭ تارتىش كۈچى پۈتۈن قۇرۇلمىنى تىرەشكە يېتىدۇ.","uning tartish küchi pütün qurulmini tireshke yétidu."]],"挽幛":[["客厅里挂着新写的挽幛。","مېھمانخانىدا يېڭى يېزىلغان تەزىيە لەۋھىسى ئېسىلىپ تۇرۇپتۇ.","méhmanxanida yéngi yézilghan teziye lewhisi ésilip turuptu."]],"提尔市":[["提尔市以古老的建筑闻名。","تىر شەھىرى قەدىمىي بىنالار بىلەن داڭلىق.","tir shehiri qedimiy binalar bilen dangliq."]],"抢掠":[["军队在占领城市后进行了抢掠。","ئارمىيە شەھەرنى ئىشغال قىلغاندىن كېيىن تالان-تاراج قىلدى.","armiye sheherni ishghal qilghandin kéyin talan-taraj qildi."]],"撑杆跳":[["撑杆跳是田径比赛中的一个项目。","تىرەك تاياق بىلەن سەكرەش يېنىك ئاتلېتىكا مۇسابىقىسىدىكى بىر تۈر.","tirek tayaq bilen sekresh yénik atlétika musabiqisidiki bir tür."]],"摩加迪休":[["摩加迪休是索马里的首都。","موگادىشۇ سومالىنىڭ پايتەختىدۇر.","mogadishu somalining paytextidur."]],"擦伤":[["他被玻璃擦伤了手臂。","ئۇ شىشە بىلەن قولىنى تىلىۋالدى.","u shishe bilen qolini tiliwaldi."]],"擦肩而过":[["他们在人群中擦肩而过。","ئۇلار ئادەم توپى ئىچىدە سۈركىلىپ ئۆتۈشتى.","ular adem topi ichide sürkilip ötüshti."]],"撤换":[["经理被撤换为新的负责人。","مۇدىر يېڭى مەسئۇل بىلەن ئالماشتۇرۇلدى.","mudir yéngi mes'ul bilen almashturuldi."]],"攘袖":[["他攘袖展示技艺。","ئۇ يەڭىنى تۈرۈپ ماھارىتىنى كۆرسەتتى.","u yengini türüp maharitini körsetti."]],"支前":[["他们积极支前，支援前线。","ئۇلار ئاكتىپلىق بىلەن ئالدىنقى سەپنى قوللاپ، ئالدىنقى سەپكە ياردەم بەردى.","ular aktipliq bilen aldinqi sepni qollap, aldinqi sepke yardem berdi."]],"政治局面":[["当前政治局面趋于稳定。","نۆۋەتتىكى سىياسىي ۋەزىيەت مۇقىملاشماقتا.","nöwettiki siyasiy weziyet muqimlashmaqta."]],"放射性最强点":[["找到放射性最强点。","رادىئاتسىيە كۈچى ئەڭ يۇقىرى نۇقتىنى تېپىڭ.","radiatsiye küchi eng yuqiri nuqtini téping."]],"政府军":[["政府军与叛军展开激烈战斗。","ھۆكۈمەت قىسىملىرى بىلەن ئىسيانچىلار ئوتتۇرىسىدا شىددەتلىك جەڭ بولدى.","hökümet qisimliri bilen isyanchilar otturisida shiddetlik jeng boldi."]],"教廷":[["教廷是天主教的中心。","پاپا ئوردىسى كاتولىك دىنىنىڭ مەركىزى.","papa ordisi katolik dinining merkizi."]],"攘外":[["国家攘外安内。","دۆلەت سىرتىدىكى دۈشمەننى توسۇپ ئىچكىنى تىنچلاندۇرىدۇ.","dölet sirtidiki düshmenni tosup ichkini tinchlanduridu."]],"数码港":[["数码港是亚洲重要的科技中心之一。","رەقەملىك پورت ئاسىيانىڭ مۇھىم پەن-تېخنىكا مەركەزلىرىنىڭ بىرىدۇر.","reqemlik port asiyaning muhim pen-téxnika merkezlirining biridur."]],"斯泰西":[["斯泰西是一名演员。","ستېيسى بىر ئارتىس.","stéysi bir artis."]],"料号":[["请确认零件的料号是否正确。","بۆلەكنىڭ ماتېرىيال نومۇرىنىڭ توغرا ياكى ئەمەسلىكىنى جەزملەشتۈرۈڭ.","bölekning matériyal nomurining toghra yaki emeslikini jezmleshtürüng."]],"斜倚":[["他斜倚在墙上休息片刻。","ئۇ تامغا يانتايىپ بىر ئاز دەم ئالدى.","u tamgha yantayip bir az dem aldi."]],"新潮":[["新潮杂志引领时尚潮流。","شىنچاۋ ژۇرنىلى مودا ئېقىمىنى يېتەكلەيدۇ.","shinchaw zhurnili moda éqimini yétekleydu."]],"敛迹":[["他敛迹潜逃，躲藏了起来。","ئۇ ئىزىنى يوشۇرۇپ قېچىپ، يوشۇرۇنۇپ قالدى.","u izini yoshurup qéchip, yoshurunup qaldi."]],"新金县":[["新金县的矿产资源丰富。","يېڭىجىن ناھىيىسىنىڭ مىنېرال بايلىقى مول.","yéngijin nahiyisining minéral bayliqi mol."]],"方块":[["这个方块是积木的一部分。","بۇ كۇب كۆپۈكمە ئويۇنچۇقنىڭ بىر قىسمى.","bu kub köpükme oyunchuqning bir qismi."]],"旗兵":[["旗兵在战场上英勇作战。","بايىراق ئەسكەرلىرى جەڭ مەيدانىدا قەھرىمانلارچە جەڭ قىلىدۇ.","bayiraq eskerliri jeng meydanida qehrimanlarche jeng qilidu."]],"旗舰店":[["商场里的旗舰店经常举办促销活动。","سودا سارىيىدىكى بايراق دۇكىنى دائىم تەشۋىقات پائالىيىتى ئۆتكۈزىدۇ.","soda sariyidiki bayraq dukini daim teshwiqat paaliyiti ötküzidu."]],"日喀则":[["日喀则位于西藏西南部。","شىگاتسې تىبەتنىڭ جەنۇبىي غەربىي قىسمىدا جايلاشقان.","shigatsé tibetning jenubiy gherbiy qismida jaylashqan."]],"明里":[["明里他装作若无其事。","ئوچۇقچىلىقتا ئۇ ھېچ ئىش بولمىغاندەك تۇردى.","ochuqchiliqta u héch ish bolmighandek turdi."]],"明德镇":[["明德镇以农业为主。","مىڭدې بازىرى ئاساسلىقى دېھقانچىلىققا تايىنىدۇ.","mingdé baziri asasliqi déhqanchiliqqa tayinidu."]],"春心":[["春心萌动让人难以平静。","باھار ھېسسىياتىنىڭ ئويغىنىشى كىشىنى تىنچسىز قىلىدۇ.","bahar héssiyatining oyghinishi kishini tinchsiz qilidu."]],"普京":[["普京是俄罗斯现任总统。","پۇتىن رۇسىيەنىڭ نۆۋەتتىكى پرېزىدېنتى.","putin rusiyening nöwettiki prézidénti."]],"普氏小羚羊":[["普氏小羚羊濒临灭绝。","پۇشى كىچىك جېيرەن يوقىلىش گىردابىدا تۇرماقتا.","pushi kichik jéyren yoqilish girdabida turmaqta."]],"景泰县":[["景泰县是甘肃省的一个农业大县。","جىڭتەي ناھىيەسى گەنسۇ ئۆلكىسىدىكى بىر يېزا ئىگىلىك چوڭ ناھىيەسى.","jingtey nahiyesi gensu ölkisidiki bir yéza igilik chong nahiyesi."]],"晤面":[["他们久别后终于晤面。","ئۇلار ئۇزۇن ئايرىلىشتىن كېيىن ئاخىرى يۈز كۆرۈشتى.","ular uzun ayrilishtin kéyin axiri yüz körüshti."]],"晨曦":[["晨曦初现，万物苏醒。","تاڭ سەھەردە، ھەممە نەرسە ئويغىنىدۇ.","tang seherde, hemme nerse oyghinidu."]],"智能卡":[["智能卡广泛应用于各种身份验证系统中。","ئەقلىي كارتىلار ھەر خىل شەخسىيەتنى دەلىللەش سىستېمىلىرىدا كەڭ قوللىنىلىدۇ.","eqliy kartilar her xil shexsiyetni delillesh sistémilirida keng qollinilidu."]],"暴虎冯河":[["他暴虎冯河，结果自食其果。","ئۇ ئەقىلسىزلىق بىلەن ئىش قىلىپ، ئاخىرى ئۆزى زىيان تارتتى.","u eqilsizliq bilen ish qilip, axiri özi ziyan tartti."]],"会哭的孩子有奶吃":[["会哭的孩子有奶吃，这是常见的说法。","يىغلايدىغان بالىنىڭ سۈتى بار، بۇ كۆپ ئۇچرايدىغان گەپ.","yighlaydighan balining süti bar, bu köp uchraydighan gep."]],"会战":[["双方在此展开激烈会战。","ئىككى تەرەپ بۇ يەردە شىددەتلىك ئۇرۇش باشلىدى.","ikki terep bu yerde shiddetlik urush bashlidi."]],"月分":[["月分分配合理。","ئاي بويىچە تەقسىملەش مۇۋاپىق.","ay boyiche teqsimlesh muwapiq."]],"暹罗":[["暹罗是泰国以前的旧称。","سيام تايلاندنىڭ ئىلگىرىكى كونا نامى ئىدى.","syam taylandning ilgiriki kona nami idi."]],"有的时候":[["有的时候，天气会突然变冷。","بەزىدە ھاۋا تۇيۇقسىز سوۋۇپ كېتىدۇ.","bezide hawa tuyuqsiz sowup kétidu."]],"木瓦":[["木瓦是古代屋顶的常见材料。","ياغاچ كاھىش قەدىمكى زاماندا ئۆگزىنىڭ ئادەتتىكى ماتېرىيالى ئىدى.","yaghach kahish qedimki zamanda ögzining adettiki matériyali idi."]],"材料科学":[["材料科学推动进步。","ماتېرىيال ئىلمى تەرەققىياتنى ئىلگىرى سۈرىدۇ.","matériyal ilmi tereqqiyatni ilgiri süridu."]],"朱厚照":[["朱厚照是明朝的一位年轻皇帝。","جۇ خۇ جاڭ مىڭ سۇلالىسىنىڭ ياش ئىمپېراتورى.","ju xu jang ming sulalisining yash impératori."]],"朱红灯":[["灯笼上画着传统的朱红灯图案。","پانۇسلارغا ئەنئەنىۋى قىزىل چىراغ نۇسخىلىرى سىزىلغان.","panuslargha en'eniwi qizil chiragh nusxiliri sizilghan."]],"东方鸻":[["东方鸻是一种迁徙性水鸟。","شەرقىي سازلىق سۇ قۇشى كۆچمەن سۇ قۇشىدۇر.","sherqiy sazliq su qushi köchmen su qushidur."]],"杞人忧天":[["杞人忧天形容过度担心。","قىي ئادىمىنىڭ ئاسماندىن قورقۇشى ھەددىدىن زىيادە ئەنسىرەشنى تەسۋىرلەيدۇ.","qiy adimining asmandin qorqushi heddidin ziyade ensireshni teswirleydu."]],"枋寮乡":[["枋寮乡位于山区。","فاڭلياۋ يېزىسى تاغلىق رايوندا جايلاشقان.","fanglyaw yézisi taghliq rayonda jaylashqan."]],"林克平大学":[["林克平大学是一所知名高校。","ئورمان كوپىڭ ئۇنىۋېرسىتېتى داڭلىق ئالىي مەكتەپ.","orman koping uniwérsitéti dangliq aliy mektep."]],"林柳莺":[["林柳莺的歌声婉转动听，令人陶醉。","لىن لىيۇيىڭنىڭ ناخشا ئاۋازى ناھايىتى يېقىملىق ۋە ئاڭلىغۇچىنى مەست قىلىدۇ.","lin liyuyingning naxsha awazi nahayiti yéqimliq we anglighuchini mest qilidu."]],"东辽县":[["东辽县历史悠久，文化丰富。","دۇڭلياۋ ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى باي.","dunglyaw nahiyisining tarixi uzun, medeniyiti bay."]],"柴油发动机":[["柴油发动机的效率比汽油发动机高。","چاي يېقىلغۇ ماتورىنىڭ ئۈنۈمى بېنزىن ماتورىنىڭكىدىن يۇقىرى.","chay yéqilghu matorining ünümi bénzin matoriningkidin yuqiri."]],"核工程":[["核工程涉及反应堆的设计与建造。","يادرو ئىنژېنېرلىقى رېئاكتورنى لايىھىلەش ۋە قۇرۇشنى ئۆز ئىچىگە ئالىدۇ.","yadro inzhénérliqi réaktorni layihilesh we qurushni öz ichige alidu."]],"桂系军阀":[["桂系军阀在历史上影响深远。","گۈي تۈزۈمىدىكى جۇڭگاۋلار تارىختا چوڭقۇر تەسىر كۆرسەتكەن.","güy tüzümidiki junggawlar tarixta chongqur tesir körsetken."]],"枚乘":[["枚乘是西汉时期的著名文学家。","مېي چېڭ غەربىي خەن سۇلالىسى دەۋرىدىكى داڭلىق ئەدىب.","méy chéng gherbiy xen sulalisi dewridiki dangliq edib."]],"果子露":[["她做了美味的果子露招待客人。","ئۇ مېھمانلارنى كۈتۈۋېلىش ئۈچۈن لەززەتلىك مېۋە شەربىتى تەييارلىدى.","u méhmanlarni kütüwélish üchün lezzetlik méwe sherbiti teyyarlidi."]],"桐城":[["桐城历史悠久，文化底蕴深厚。","تۇڭچېڭنىڭ تارىخى ئۇزۇن، مەدەنىيەت ئاساسى چوڭقۇر.","tungchéngning tarixi uzun, medeniyet asasi chongqur."]],"棒子":[["棒子可以用来制作各种美食，比如棒子面。","قوناق دانىسىدىن تۈرلۈك تائاملىرىنى تەييارلاشقا بولىدۇ، مەسىلەن قوناق ئۇنىدىن.","qonaq danisidin türlük taamlirini teyyarlashqa bolidu, mesilen qonaq unidin."]],"棒材":[["棒材是制造家具的重要原材料之一。","تاياقسىمان ماتېرىيال ئۆي جاھازىلىرى ياساشتا مۇھىم خام ماتېرىياللارنىڭ بىرىدۇر.","tayaqsiman matériyal öy jahaziliri yasashta muhim xam matériyallarning biridur."]],"棕脸鹟莺":[["棕脸鹟莺的面部呈棕色。","قوڭۇر يۈزلۈك چىۋىق سېرىقنىڭ يۈزى قوڭۇر رەڭدە.","qongur yüzlük chiwiq sériqning yüzi qongur rengde."]],"棕绳":[["棕绳结实耐用，适合户外使用。","قوڭۇر ئارغامچا پۇختا ھەم چىداملىق بولۇپ، سىرتقا ئىشلىتىشكە ماس كېلىدۇ.","qongur arghamcha puxta hem chidamliq bolup, sirtqa ishlitishke mas kélidu."]],"植物人":[["植物人处于无意识状态。","ئۆسۈملۈك ئادەم ھۇشسىز ھالەتتە بولىدۇ.","ösümlük adem hushsiz halette bolidu."]],"杨利伟":[["杨利伟是中国首位宇航员。","ياڭ لىۋېي جۇڭگونىڭ تۇنجى ئالەم ئۇچقۇچىسى.","yang liwéy junggoning tunji alem uchquchisi."]],"榴莲":[["榴莲的气味独特，让人爱恨交织。","دۇرياننىڭ پۇرىقى ئالاھىدە، كىشىلەرنى سۆيۈش ۋە ئۆچ كۆرۈش ئارىسىدا قالدۇرىدۇ.","duryanning puriqi alahide, kishilerni söyüsh we öch körüsh arisida qalduridu."]],"楔形文字":[["楔形文字是古代苏美尔人使用的文字系统。","تارغاقسىمان يېزىق قەدىمكى شۇمېرلار ئىشلەتكەن يېزىق سىستېمىسىدۇر.","targhaqsiman yéziq qedimki shumérlar ishletken yéziq sistémisidur."]],"横滨":[["横滨是日本的重要港口。","يوكوھاما ياپونىيەنىڭ مۇھىم پورتى.","yokohama yaponiyening muhim porti."]],"横膈膜":[["横膈膜分隔了胸腔和腹腔。","كۆندىلەڭ پەردە كۆكرەك قەپىسى بىلەن قارىن قەپىسىنى ئايرىيدۇ.","köndileng perde kökrek qepisi bilen qarin qepisini ayriydu."]],"横征暴敛":[["横征暴敛导致民不聊生。","كۆندىلەڭ زورلۇق بېسىم خەلقنىڭ تۇرمۇشىنى ناچارلاشتۇردى.","köndileng zorluq bésim xelqning turmushini nacharlashturdi."]],"横跨":[["大桥横跨了宽阔的江面。","كۆۋرۈك كەڭ دەريا يۈزىدىن كېسىپ ئۆتتى.","köwrük keng derya yüzidin késip ötti."]],"横骨":[["这根横骨非常坚硬。","بۇ كۆندەلەڭ سۆڭەك ئىنتايىن قاتتىق.","bu köndeleng söngek intayin qattiq."]],"树突状细胞":[["树突状细胞是免疫系统的关键。","دەرەخسىمان ھۈجەيرىلەر ئىممۇنىتېت سىستېمىسىنىڭ ئاچقۇچىدۇر.","derexsiman hüjeyriler immunitét sistémisining achquchidur."]],"欧查果":[["这种欧查果是当地特有的水果。","بۇ خىل ياۋروپا ئەنجۈرى يەرلىك ئالاھىدە مېۋە.","bu xil yawropa enjüri yerlik alahide méwe."]],"欧盟委员会":[["欧盟委员会负责制定共同政策。","ياۋروپا ئىتتىپاقى كومىتېتى ئورتاق سىياسەت تۈزۈشكە مەسئۇلدۇر.","yawropa ittipaqi komitéti ortaq siyaset tüzüshke mes'uldur."]],"次长":[["次长负责协助部长工作。","ئىككىنچى دەرىجىلىك باشلىق مىنىستىرنىڭ خىزمىتىگە ياردەم قىلىشقا مەسئۇل.","ikkinchi derijilik bashliq ministirning xizmitige yardem qilishqa mes'ul."]],"正极":[["电池的正极连接正极。","باتارېيەنىڭ مۇسبەت قۇتۇبى مۇسبەت قۇتۇپقا ئۇلىنىدۇ.","bataréyening musbet qutubi musbet qutupqa ulinidu."]],"步调":[["他们的步调完全一致。","ئۇلارنىڭ قەدىمى پۈتۈنلەي بىردەك.","ularning qedimi pütünley birdek."]],"正品":[["这是正品，质量很好。","بۇ ئەسلىي مەھسۇلات، سۈپىتى ناھايىتى ياخشى.","bu esliy mehsulat, süpiti nahayiti yaxshi."]],"正宁":[["正宁是甘肃省的一个县。","جېڭنىڭ گەنسۇ ئۆلكىسىدىكى بىر ناھىيە.","jéngning gensu ölkisidiki bir nahiye."]],"杀人鲸":[["杀人鲸其实是海洋中的顶级捕食者。","ئۆلتۈرگۈچى كىت ھەقىقەتەن دېڭىزدىكى ئەڭ يۇقىرى دەرىجىلىك يىرتقۇچتۇر.","öltürgüchi kit heqiqeten déngizdiki eng yuqiri derijilik yirtquchtur."]],"归隐":[["他决定归隐山林，远离尘嚣。","ئۇ تاغ-ئورمانغا چېكىنىپ، دۇنياۋى شاۋقۇندىن يىراق تۇرۇشنى قارار قىلدى.","u tagh-ormangha chékinip, dunyawi shawqundin yiraq turushni qarar qildi."]],"毛边":[["这本书的毛边设计很特别。","بۇ كىتابنىڭ خام گىرۋەك لايىھەسى ئىنتايىن ئالاھىدە.","bu kitabning xam girwek layihesi intayin alahide."]],"毛里求斯":[["毛里求斯是印度洋岛国。","ماۋرىتىيۇس ھىندى ئوكيانىدىكى ئارال دۆلىتى.","mawritiyus hindi okyanidiki aral döliti."]],"毁损":[["文物遭到严重毁损。","مەدەنىي يادىكارلىقلار ئېغىر دەرىجىدە بۇزۇلدى.","medeniy yadikarliqlar éghir derijide buzuldi."]],"民主革命":[["这场民主革命改变了国家命运。","بۇ دېموكراتىك ئىنقىلاب دۆلەتنىڭ تەقدىرىنى ئۆزگەرتتى.","bu démokratik inqilab döletning teqdirini özgertti."]],"民国通俗演义":[["《民国通俗演义》是经典历史小说。","«مىنگو ئومۇمىي چۈشەندۈرۈش رومانى» كلاسسىك تارىخىي روماندۇر.","«mingo omumiy chüshendürüsh romani» klassik tarixiy romandur."]],"水筲":[["这个水筲容量很大。","بۇ سۇ چېلىكىنىڭ سىغىمى ناھايىتى چوڭ.","bu su chélikining sighimi nahayiti chong."]],"水力压裂":[["水力压裂是一种通过高压水开采石油的技术。","سۇ كۈچى بىلەن يېرىش ئېچىش يۇقىرى بېسىملىق سۇ ئارقىلىق نېفىت ئېچىش تېخنىكىسى.","su küchi bilen yérish échish yuqiri bésimliq su arqiliq néfit échish téxnikisi."]],"汶川地震":[["汶川地震造成了巨大损失。","ۋېنچۈەن يەر تەۋرەشى زور زىيان كەلتۈردى.","wénchüen yer tewreshi zor ziyan keltürdi."]],"江都":[["江都是中国古代的重要城市。","جياڭدۇ جۇڭگونىڭ قەدىمكى زاماندىكى مۇھىم شەھىرى.","jyangdu junggoning qedimki zamandiki muhim shehiri."]],"江酌之喜":[["江酌之喜是一种传统的饮酒习俗。","جياڭجۇنىڭ خۇشاللىقى ئەنئەنىۋى بىر خىل ھاراق ئىچىش ئادەتى.","jyangjuning xushalliqi en'eniwi bir xil haraq ichish adeti."]],"汽车展览会":[["汽车展览会上展示了最新车型。","ئاپتوموبىل كۆرگەزمىسىدە ئەڭ يېڭى تىپلار كۆرسىتىلدى.","aptomobil körgezmiside eng yéngi tiplar körsitildi."]],"汽车号牌":[["汽车号牌必须清晰可见且符合规定。","ئاپتوموبىل نومۇر تاختىسى ئېنىق كۆرۈنۈشى ۋە بەلگىلىمىگە ئۇيغۇن بولۇشى كېرەك.","aptomobil nomur taxtisi éniq körünüshi we belgilimige uyghun bolushi kérek."]],"没经验":[["他做事总是没经验，容易出错。","ئۇ ئىش قىلغاندا ھەمىشە تەجرىبىسىز، خاتالىق سادىر قىلىشى ئاسان.","u ish qilghanda hemishe tejribisiz, xataliq sadir qilishi asan."]],"河村":[["河村坐落在山脚下。","خېكۈن كەنتى تاغ ئېتىكىدە جايلاشقان.","xékün kenti tagh étikide jaylashqan."]],"油汗":[["夏天运动后，脸上全是油汗。","يازدا تەنھەرىكەت قىلغاندىن كېيىن، يۈزى پۈتۈنلەي يېغ تەرگە چۆمۈلگەن.","yazda tenheriket qilghandin kéyin, yüzi pütünley yégh terge chömülgen."]],"油耗":[["这款车的油耗很低。","بۇ ماشىنىنىڭ ماي سەرپىياتى بەك تۆۋەن.","bu mashinining may serpiyati bek töwen."]],"波茨坦公告":[["波茨坦公告结束了二战。","پوتسدام ئېلاننامىسى ئىككىنچى دۇنيا ئۇرۇشىنى ئاخىرلاشتۇردى.","potsdam élannamisi ikkinchi dunya urushini axirlashturdi."]],"波托马克河":[["波托马克河是美国的著名河流。","پوتوماك دەرياسى ئامېرىكىنىڭ مەشھۇر دەرياسى.","potomak deryasi amérikining meshhur deryasi."]],"波斯猫":[["波斯猫是一种常见的家猫品种。","پارس مۈشۈكى ئۆي مۈشۈكلىرىنىڭ ئادەتتىكى بىر تۈرى.","pars müshüki öy müshüklirining adettiki bir türi."]],"波德申":[["波德申是缅甸的一个港口城市。","پورت دىكسون بىرمىنىڭ بىر پورت شەھىرىدۇر.","port dikson birmining bir port shehiridur."]],"泰兴市":[["泰兴市是江苏省的重要城市。","تەيشىڭ شەھىرى جياڭسۇ ئۆلكىسىنىڭ مۇھىم شەھىرى.","teyshing shehiri jyangsu ölkisining muhim shehiri."]],"流速":[["河流的流速因季节变化而不同。","دەريانىڭ ئېقىش سۈرئىتى پەسىلگە قاراپ ئوخشىمايدۇ.","deryaning éqish sür'iti pesilge qarap oxshimaydu."]],"流食":[["病人需要吃流食来恢复健康。","بېمار ساغلاملىقىنى ئەسلىگە كەلتۈرۈش ئۈچۈن سۇيۇق ئوزۇق يېيىشى كېرەك.","bémar saghlamliqini eslige keltürüsh üchün suyuq ozuq yéyishi kérek."]],"洪福齐天":[["他洪福齐天，一生顺遂。","ئۇنىڭ بەخت-سائادىتى ئاسمانغا تەڭ، پۈتۈن ھاياتى ئوڭۇشلۇق ئۆتتى.","uning bext-saaditi asmangha teng, pütün hayati ongushluq ötti."]],"流程表":[["流程表帮助管理每个环节。","جەريان جەدۋىلى ھەر بىر ھالقىنى باشقۇرۇشقا ياردەم بېرىدۇ.","jeryan jedwili her bir halqini bashqurushqa yardem béridu."]],"活动人士":[["活动人士经常组织环保抗议。","پائالىيەتچىلەر مۇھىت قوغداش نامايىشىنى دائىم تەشكىللەيدۇ.","paaliyetchiler muhit qoghdash namayishini daim teshkilleydu."]],"浴血苦战":[["他们浴血苦战，终于守住了阵地。","ئۇلار قانلىق كۈرەش قىلىپ، ئاخىرىدا مەيداننى قوغداپ قالدى.","ular qanliq küresh qilip, axirida meydanni qoghdap qaldi."]],"海绵宝宝":[["海绵宝宝住在菠萝屋里。","دېڭىز ئىسپىنجى بوۋىسى ئاناناس ئۆيىدە تۇرىدۇ.","déngiz ispinji bowisi ananas öyide turidu."]],"清代":[["清代是中国历史上的一个重要时期。","چىڭ سۇلالىسى جۇڭگو تارىخىدىكى مۇھىم بىر دەۋر.","ching sulalisi junggo tarixidiki muhim bir dewr."]],"清正":[["他为人清正，深受同事信赖。","ئۇ ئەخلاقى پاك بولۇپ، خىزمەتداشلىرىنىڭ ئىشەنچىسىگە ئېرىشكەن.","u exlaqi pak bolup, xizmetdashlirining ishenchisige érishken."]],"测天":[["古代人通过观测天象来预测季节。","قەدىمكى كىشىلەر ئاسمان جىسىملىرىنى كۆزىتىش ئارقىلىق پەسىللەرنى مۆلچەرلىگەن.","qedimki kishiler asman jisimlirini közitish arqiliq pesillerni mölcherligen."]],"测试器":[["这个测试器可以检测电路的故障。","بۇ سىناق ئۈسكۈنىسى ئېلېكتر توك يولىنىڭ كاشىلىسىنى تەكشۈرەلەيدۇ.","bu sinaq üskünisi éléktr tok yolining kashilisini tekshüreleydu."]],"湄公河三角洲":[["湄公河三角洲物产丰富。","مېكونگ دەرياسى دېلتىسىنىڭ مەھسۇلاتى مول.","mékong deryasi déltisining mehsulati mol."]],"准的":[["这个答案很准的。","بۇ جاۋاب ئىنتايىن ئېنىق.","bu jawab intayin éniq."]],"滑环":[["滑环用于连接不同的部件。","تېيىلغۇچ ھالقا ئوخشىمىغان زاپچاسلارنى ئۇلاشقا ئىشلىتىلىدۇ.","téyilghuch halqa oxshimighan zapchaslarni ulashqa ishlitilidu."]],"温标":[["温标是测量温度的标准体系。","تېمپېراتۇرا ئۆلچىمى تېمپېراتۇرىنى ئۆلچەيدىغان ئۆلچەم سىستېمىسى.","témpératura ölchimi témpératurini ölcheydighan ölchem sistémisi."]],"温文":[["他为人温文，举止优雅得体。","ئۇ كىشى مۇلايىم، ئەدەپ-ئەخلاقى ئېلىپبەلىك.","u kishi mulayim, edep-exlaqi élipbelik."]],"汤面":[["我吃了一碗热汤面。","مەن بىر چىنە ئىسسىق شورپا لەڭمەن يېدىم.","men bir chine issiq shorpa lengmen yédim."]],"源城":[["源城是古代的重要城池。","يۈەنچېڭ قەدىمكى زاماندىكى مۇھىم شەھەردۇر.","yüenchéng qedimki zamandiki muhim sheherdur."]],"汉中市":[["汉中市是旅游胜地。","خەنزۇڭ شەھىرى ساياھەت ئورنى.","xenzung shehiri sayahet orni."]],"潭子乡":[["潭子乡以美丽的风景闻名。","تەنزى يېزىسى گۈزەل مەنزىرىسى بىلەن تونۇلغان.","tenzi yézisi güzel menzirisi bilen tonulghan."]],"滥调":[["他的演讲全是老生常谈的滥调。","ئۇنىڭ نۇتۇقى پۈتۈنلەي كونا سۆزلەرنىڭ تەكرارى ئىدى.","uning nutuqi pütünley kona sözlerning tekrari idi."]],"浏阳市":[["浏阳市是湖南省的一个城市。","ليۇياڭ شەھىرى خۇنەن ئۆلكىسىدىكى بىر شەھەر.","lyuyang shehiri xunen ölkisidiki bir sheher."]],"滨海边疆区":[["滨海边疆区位于俄罗斯远东地区。","دېڭىز بويى ئۆلكىسى روسىيەنىڭ يىراق شەرق رايونىدا جايلاشقان.","déngiz boyi ölkisi rosiyening yiraq sherq rayonida jaylashqan."]],"濡湿":[["雨水将他的衣服濡湿，十分狼狈。","يېغىن ئۇنىڭ كىيىملىرىنى ھۆل قىلىۋەتتى، ئۇ بەك ناھايىتى ئوڭايسىز ھالغا چۈشتى.","yéghin uning kiyimlirini höl qiliwetti, u bek nahayiti ongaysiz halgha chüshti."]],"滥套子":[["这个方案不过是老套子的滥套子。","بۇ پىلان پەقەت كونا ئۇسۇلنىڭ تەكرارلىنىشى.","bu pilan peqet kona usulning tekrarlinishi."]],"滥权":[["滥权会损害公共利益，必须受到谴责。","ھوقۇقنى سۇيىئىستېمال قىلىش ئاممىۋى مەنپەئەتكە زىيان يەتكۈزىدۇ، چوقۇم ئەيىبلىنىشى كېرەك.","hoquqni suyiistémal qilish ammiwi menpeetke ziyan yetküzidu, choqum eyiblinishi kérek."]],"滤波":[["滤波技术可以去除信号中的噪声。","سىگنال سۈزۈش تېخنىكىسى سىگنالدىكى شاۋقۇننى يوقىتالايدۇ.","signal süzüsh téxnikisi signaldiki shawqunni yoqitalaydu."]],"火炉":[["冬天，他坐在火炉旁取暖。","قىشتا ئۇ ئوت پېچىكىنىڭ يېنىدا ئولتۇرۇپ ئىسسىندى.","qishta u ot péchikining yénida olturup issindi."]],"火影忍者":[["《火影忍者》是一部热门动漫作品。","«ئوت سايىسى نىنجا» ئالقىشقا ئېرىشكەن بىر ئانىمې ئەسىرىدۇر.","«ot sayisi ninja» alqishqa érishken bir animé esiridur."]],"为时过早":[["现在下结论还为时过早。","ھازىر خۇلاسە چىقىرىش تېخى بەك بالدۇر.","hazir xulase chiqirish téxi bek baldur."]],"烃蜡":[["烃蜡常用于制造低熔点的工业材料。","ئالكان مومى ئادەتتە تۆۋەن ئېرىش نۇقتىلىق سانائەت ماتېرىياللىرىنى ئىشلەپچىقىرىشتا ئىشلىتىلىدۇ.","alkan momi adette töwen érish nuqtiliq sanaet matériyallirini ishlepchiqirishta ishlitilidu."]],"烽烟四起":[["烽烟四起，预示着战争即将爆发。","ئوت سىگنالى تۆت تەرەپكە تارقاپ، ئۇرۇشنىڭ پات يېقىندا باشلىنىدىغانلىقىنى ئالدىن كۆرسىتىدۇ.","ot signali töt terepke tarqap, urushning pat yéqinda bashlinidighanliqini aldin körsitidu."]],"无极县":[["无极县位于河北省。","ۋۇجى ناھىيىسى خېبېي ئۆلكىسىدە جايلاشقان.","wuji nahiyisi xébéy ölkiside jaylashqan."]],"无所作为":[["他多年努力，却无所作为。","ئۇ كۆپ يىل تىرىشسىمۇ، ھېچقانداق نەتىجە قازالمىدى.","u köp yil tirishsimu, héchqandaq netije qazalmidi."]],"无所属":[["这些物品无所属，无人认领。","بۇ بۇيۇملارنىڭ ئىگىسى يوق، ھېچكىم ئىگىلىك ئالمايدۇ.","bu buyumlarning igisi yoq, héchkim igilik almaydu."]],"无期徒刑":[["罪犯被判处无期徒刑。","جىنايەتچى ئۆمۈر بويى قاماق جازاسىغا ھۆكۈم قىلىندى.","jinayetchi ömür boyi qamaq jazasigha höküm qilindi."]],"无核化":[["国家致力于实现无核化。","دۆلەت يادروسىزلىشىشنى ئەمەلگە ئاشۇرۇشقا تىرىشىدۇ.","dölet yadrosizlishishni emelge ashurushqa tirishidu."]],"烧锅":[["烧锅时要注意火候。","قازاننى ئوتقا قويغاندا ئوت تېمپىنىغا دىققەت قىلىش كېرەك.","qazanni otqa qoyghanda ot témpinigha diqqet qilish kérek."]],"无毒不丈夫":[["无毒不丈夫，大丈夫当有所作为。","زەھەرسىز ئەر بولماس، ھەقىقىي ئەر چوقۇم بىرەر ئىش قىلىشى كېرەك.","zehersiz er bolmas, heqiqiy er choqum birer ish qilishi kérek."]],"牙刷":[["每天用牙刷清洁牙齿很重要。","ھەر كۈنى چىش چوتكىسى بىلەن چىشنى تازىلاش مۇھىم.","her küni chish chotkisi bilen chishni tazilash muhim."]],"牛油":[["牛油是烹饪常用的油脂。","كالا مېيى تاماق ئېتىشتە كۆپ ئىشلىتىلىدىغان ياغ.","kala méyi tamaq étishte köp ishlitilidighan yagh."]],"牌坊":[["牌坊是古代纪念建筑的标志。","تاق ئەسلىدە قەدىمكى ئەسكەرتىش بىنالىرىنىڭ بەلگىسى ئىدى.","taq eslide qedimki eskertish binalirining belgisi idi."]],"燃料芯块":[["燃料芯块是核能发电的重要材料之一。","يېقىلغۇ يادروسى يادرو ئېنېرگىيىسى ئارقىلىق توك چىقىرىشنىڭ مۇھىم ماتېرىياللىرىنىڭ بىرى.","yéqilghu yadrosi yadro énérgiyisi arqiliq tok chiqirishning muhim matériyallirining biri."]],"燃烧剂":[["燃烧剂用于加速化学反应的过程。","يېقىش دورىسى خىمىيىلىك رېئاكسىيە جەريانىنى تېزلىتىش ئۈچۈن ئىشلىتىلىدۇ.","yéqish dorisi ximiyilik réaksiye jeryanini tézlitish üchün ishlitilidu."]],"燕梳":[["古代女子用燕梳梳妆。","قەدىمكى زاماندا ئاياللار قارلىغاچ تارغاق بىلەن چاچ تارايتتى.","qedimki zamanda ayallar qarlighach targhaq bilen chach taraytti."]],"狼人":[["狼人月圆之夜会变成野兽。","بۆرە ئادەم تولۇن ئاي كېچىسىدە ياۋايى ھايۋانغا ئايلىنىدۇ.","böre adem tolun ay kéchiside yawayi haywangha aylinidu."]],"猜不透":[["他的心思真让人猜不透。","ئۇنىڭ كۆڭلىدىكىنى ھەقىقەتەن پەرەز قىلغىلى بولمايدۇ.","uning könglidikini heqiqeten perez qilghili bolmaydu."]],"猜枚":[["他们玩猜枚游戏来打发时间。","ئۇلار ۋاقىت ئۆتكۈزۈش ئۈچۈن پەرەز ئويۇنى ئوينىدى.","ular waqit ötküzüsh üchün perez oyuni oynidi."]],"牡羊座":[["牡羊座是黄道十二宫之一。","قوزىچاق بۇرجى ئون ئىككى بۇرجىنىڭ بىرى.","qozichaq burji on ikki burjining biri."]],"牡鹿":[["牡鹿是森林中的动物。","بۇغا ئورماندىكى ھايۋان.","bugha ormandiki haywan."]],"牢靠":[["这个锁非常牢靠。","بۇ قۇلۇپ ئىنتايىن پۇختا.","bu qulup intayin puxta."]],"玉头姬鹟":[["这种玉头姬鹟羽毛鲜艳。","بۇ خىل يۈتۇ جىمېي چىمىنىڭ پەيلىرى پارقىراق.","bu xil yütu jiméy chimining peyliri parqiraq."]],"琐碎":[["琐碎的日常事务让人疲惫不堪。","ئۇششاق كۈندىلىك ئىشلار كىشىنى ھارغىتىدۇ.","ushshaq kündilik ishlar kishini harghitidu."]],"环境行动主义":[["环保人士推动环境行动主义。","مۇھىت قوغدىغۇچىلار مۇھىت ھەرىكەتچىلىكىنى ئىلگىرى سۈرىدۇ.","muhit qoghdighuchilar muhit heriketchilikini ilgiri süridu."]],"环形山":[["环形山是陨石撞击的产物。","ھالقە تاغلار مېتېئورىت سوقۇلۇشىنىڭ مەھسۇلى.","halqe taghlar météorit soqulushining mehsuli."]],"班门弄斧":[["他在专家面前班门弄斧，显得很不明智。","ئۇ مۇتەخەسسىسلەرنىڭ ئالدىدا ئۆزىنى كۆرسىتىپ، ئىنتايىن ئەقىلسىزلىق قىلىپتۇ.","u mutexessislerning aldida özini körsitip, intayin eqilsizliq qiliptu."]],"男单":[["男单比赛今天正式开始了。","ئەرلەر يەككە مۇسابىقىسى بۈگۈن رەسمىي باشلاندى.","erler yekke musabiqisi bügün resmiy bashlandi."]],"甲辰":[["甲辰年运势起伏较大。","جياچېن يىلىنىڭ تەقدىرى ئۆرلەش-چۈشۈشى بىر قەدەر چوڭ.","jyachén yilining teqdiri örlesh-chüshüshi bir qeder chong."]],"画插图者":[["画插图者需要兼具文字与视觉表达能力。","سۈرەت ئىلاۋە قىلغۇچى تېكىست ۋە كۆرۈش ئىپادىلەش ئىقتىدارىغا ھەم ئىگە بولۇشى كېرەك.","süret ilawe qilghuchi tékist we körüsh ipadilesh iqtidarigha hem ige bolushi kérek."]],"疲困":[["长途旅行让他感到疲困。","ئۇزۇن سەپەر ئۇنى چارچىتىپ ھالسىز قىلدى.","uzun seper uni charchitip halsiz qildi."]],"男厕":[["男厕里排着长长的队伍。","ئەرلەر ھاجەتخانىسىدا ئۇزۇن ئۆچرەت تىزىلغان.","erler hajetxanisida uzun öchret tizilghan."]],"男性主义":[["男性主义主张男女平等。","ئەرلىك تەرەپدارلىقى ئەر-ئايال باراۋەرلىكىنى تەشەببۇس قىلىدۇ.","erlik terepdarliqi er-ayal barawerlikini teshebbus qilidu."]],"痛批":[["专家对方案进行了痛批。","مۇتەخەسسىسلەر پىلاننى قاتتىق تەنقىد قىلدى.","mutexessisler pilanni qattiq tenqid qildi."]],"痊愈":[["他经过治疗已经痊愈。","ئۇ داۋالاشتىن كېيىن ساقايىپ كەتتى.","u dawalashtin kéyin saqayip ketti."]],"疑犯":[["警方锁定了主要疑犯。","ساقچىلار ئاساسلىق گۇماندارنى بەلگىلىدى.","saqchilar asasliq gumandarni belgilidi."]],"发软":[["煮过头的米饭会变得发软。","ئېشىپ كەتكەن گۈرۈچ يۇمشاپ كېتىدۇ.","éship ketken gürüch yumshap kétidu."]],"发电厂":[["发电厂是重要的能源基地。","توك چىقىرىش زاۋۇتى مۇھىم ئېنېرگىيە بازىسىدۇر.","tok chiqirish zawuti muhim énérgiye bazisidur."]],"异言":[["他的异言令人震惊。","ئۇنىڭ ئوخشىمىغان سۆزلىرى كىشىلەرنى ھەيران قالدۇردى.","uning oxshimighan sözliri kishilerni heyran qaldurdi."]],"白面书生":[["他看起来像个白面书生。","ئۇ ئاق يۈزلۈك كىتابخۇمارغا ئوخشايدۇ.","u aq yüzlük kitabxumargha oxshaydu."]],"百乐餐":[["这家餐厅主打百乐餐。","بۇ رېستوراندا ئاساسلىقى يۈز خىل لەززەتلىك تاماق سېتىلىدۇ.","bu réstoranda asasliqi yüz xil lezzetlik tamaq sétilidu."]],"硝酸钙":[["硝酸钙用于土壤改良。","نىترات كالتسىي تۇپراق ياخشىلاشتا ئىشلىتىلىدۇ.","nitrat kaltsiy tupraq yaxshilashta ishlitilidu."]],"研修员":[["这位研修员在培训中表现出色。","بۇ ئۆگەنچى خادىم تەربىيىلەشتە ئالاھىدە ئىپادىلىدى.","bu ögenchi xadim terbiyileshte alahide ipadilidi."]],"石斑鱼":[["石斑鱼是一种味道鲜美的海鱼。","تاش بېلىقى بولسا تەمى ئېسىل بىر خىل دېڭىز بېلىقى.","tash béliqi bolsa temi ésil bir xil déngiz béliqi."]],"累觉不爱":[["工作太累，让我累觉不爱。","خىزمەت بەك چارچىتىۋەتتى، مېنى چارچاشتىن زېرىكتۈرۈۋەتتى.","xizmet bek charchitiwetti, méni charchashtin zériktürüwetti."]],"细香葱":[["细香葱常用于菜肴的点缀和调味。","ئىنچىكە كۆك پىياز كۆپىنچە تائامغا زىننەت ۋە تەم بېرىش ئۈچۈن ئىشلىتىلىدۇ.","inchike kök piyaz köpinche taamgha zinnet we tem bérish üchün ishlitilidu."]],"终了":[["会议终了后大家离开了。","يىغىن ئاخىرلاشقاندىن كېيىن ھەممەيلەن ئايرىلدى.","yighin axirlashqandin kéyin hemmeylen ayrildi."]],"紫草":[["紫草具有清热解毒的功效。","بىنەپشە ئوت ئىسسىقنى چىقىرىش ۋە زەھەرنى قايتۇرۇش ئۈنۈمىگە ئىگە.","binepshe ot issiqni chiqirish we zeherni qayturush ünümige ige."]]};
